programs.sol:
"""A sparse lexical response to evaluative characters and document openings.

Strong negative values mark isolated 善 (good), 恶/惡/悪 (evil), 擅
(adept), 暗 (dark), and the Korean syllables 선/악. Compounds have weaker
responses: this is not a general sentiment classifier. The colon in an opening
'Title:' and the 'php' in an opening '<?php' are separate positive cues.
Document-initial code declarations/comments and test labels have smaller
responses. Two Chinese compound continuations are negative. Split UTF-8
characters are recognized too, with a larger response for split 悪. Paired
middle dots are positive; everything else is zero. State resets per document.
"""

READS = ()

# Evaluative characters, with script-specific observed response sizes.
CHARACTERS = {
    '善': -7.3,  # good, virtuous
    '恶': -8.2,  # evil (simplified)
    '惡': -4.7,  # evil (traditional)
    '悪': -5.6,  # evil (Japanese)
    '擅': -6.0,  # adept
    '暗': -2.7,  # dark
    '丑': -2.3,  # ugly
    '臭': -2.0,  # foul-smelling
    '劣': -1.3,  # inferior
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, tail = 0, '', b''
    else:
        _, position, previous, tail = carry
        position += 1
    raw = prefix.token_bytes[-1]
    token = raw.decode('utf-8', errors='replace')
    word = token.strip()
    value = 0.0
    if position == 1 and previous == 'Title' and token == ':':
        value = 13.97
    elif position == 1 and previous == '<?' and token == 'php':
        value = 1.79
    elif position == 0 and word in {'int', 'char', 'def'}:
        value = -1.2 if token.startswith(' ') else -2.0
    elif position == 0 and word in {'function', 'const'}:
        value = -1.7 if word == 'function' else -1.1
    elif position == 0 and word == '//':
        value = 1.0 if '\n' in token else -2.0
    elif position == 0 and word == '/*':
        value = -1.0
    elif position == 0 and word.lower() in {'test', 'tests'}:
        value = 1.5
    elif previous == '改善' and word == '了':
        value = -1.7  # perfective suffix after 'improve'
    elif previous == '善' and word in {'于', '於'}:
        value = -1.4  # completion of 'be good at'
    elif word in CHARACTERS:
        value = CHARACTERS[word]
    elif word == '선':
        value = -2.4 if token.startswith(' ') else -2.1
    elif word == '악':
        value = -1.4
    elif '善' in word:
        value = -2.0
        if word == '改善':
            value = -2.6
        elif word == '善于':
            value = -3.8
        elif word == '善良':
            value = -1.1
    elif '恶' in word or '惡' in word:
        value = -2.4 if word == '恶劣' else -0.9
    elif word == '暴力':
        value = -1.8
    elif word == '··':
        value = 0.65
    # Recognize an ideograph completed by a continuation-byte token.
    elif raw and 0x80 <= raw[0] < 0xC0:
        completed = (tail + raw).decode('utf-8', errors='replace')
        if completed:
            value = CHARACTERS.get(completed[-1], 0.0)
            if completed[-1] == '悪':
                value *= 2.0
    return (doc, position, token, (tail + raw)[-3:]), value

"""A spelling-based approximation of an ou-fragment response.

Track the current alphabetic word fragment, resetting between documents.
Fold case and accents, and map Greek omicron/upsilon to o/u. Respond
strongly when ou crosses a token boundary or a short piece follows ou.
Otherwise favor short pieces ending near ou in uncommon English word
fragments, with a larger response for recognizable French fragments.
Unrelated tokens get zero. Token-specific strengths are not modeled.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=8192)
def normalize(s):
    s = ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                if not unicodedata.combining(c))
    return s.replace('ο', 'o').replace('υ', 'u')

@lru_cache(maxsize=8192)
def frequency(s, language):
    return zipf_frequency(s, language)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '')
    _, word = carry
    s = normalize(prefix.token_strings[-1])
    before = word if s[:1].isalpha() else ''
    m = re.search(r'[^\W\d_]+$', before + s)
    word = m.group()[-60:] if m else ''
    carry = (doc, word)
    crossing = before.endswith('o') and s.startswith('u')
    if 'ou' not in s and not crossing and 'ou' not in before[-8:]:
        return carry, 0.0
    length = len(s.strip())
    if before.endswith('ou'):
        return carry, 2.66 if length <= 3 else 0.66
    if crossing:
        return carry, 3.78
    if frequency(word, 'en') > 3.115:
        return carry, 0.083
    distance = len(word) - word.rfind('ou') - 2 if 'ou' in word else 99
    if distance > 1:
        return carry, 0.208
    if length > 3:
        return carry, 0.359
    return carry, 1.415 if frequency(word, 'fr') <= 1.455 else 2.675

"""An onset pulse that usually vanishes when a different token arrives.

ASCII letter tokens receive larger pulses when they are rarer in English,
with small case, spacing, and length adjustments. Other token types use
coarse baselines; import/package and comment/heading starts are weaker.
Uniform repetition preserves the pulse. Opening '12' and 'Title:' have
large second-token pulses; '122' has a smaller third-token pulse.
Most individual-token variation and later activity are not modeled.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def onset(text):
    if text == '<|im_start|>':
        return 2.48
    word = text.strip()
    if not word:
        if '\n' in text:
            return 1.8
        if '\t' in text:
            return 0.1 if len(text) == 1 else 2.5
        return min(3.0, 0.4 + 0.1 * len(text))
    if word.isdecimal():
        return 1.6
    if text in {'import', 'package'}:
        return -1.5
    if text.startswith(('#', '//', '/*')):
        return -0.8
    if word.isalpha():
        if not word.isascii():
            return 2.9
        frequency = max(0.0, zipf_frequency(word, 'en') - 3.0)
        return max(0.0, 3.25 - 0.5 * frequency
                   - 0.27 * text.startswith(' ')
                   + 0.11 * word[0].isupper()
                   + 0.30 * (len(word) == 1))
    return 1.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, 0, text, True, text), onset(text)

    _, position, first, uniform, opening = carry
    position += 1
    uniform = (uniform and prefix.token_bytes[-1]
               == prefix.token_bytes[-position - 1])
    value = onset(text) if uniform else 0.0
    if position == 1:
        if first == '1' and text == '2':
            value = 13.48
        elif first == 'Title' and text == ':':
            value = 13.26
    elif position == 2 and opening == '12' and text == '2':
        value = 6.37
    opening = opening + text if position < 2 else ''
    return (doc, position, first, uniform, opening), value

"""Approximate scalar-word and assignment-sign responses.

Restrictive/additive modifiers get larger responses after possible subjects.
Selection-of phrases and degree comparisons are positive; assignment-looking
spaced equals signs are negative. These are coarse text rules, not a full
syntactic analysis. Keep only 160 characters of context per document.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
SUBJECTS = set('i you he she it we they who which that this'.split())
AUXILIARIES = set(('am is are was were be been being can could will would '
                   'shall should may might must have has had do does did').split())
FUNCTION_WORDS = AUXILIARIES | set((
    'a an the and or but if as than to of for in on at by with from not no '
    'then so now very more less only just while me him her us them').split())
# Each row is (ordinary use, after a possible noun subject, after a pronoun).
MODIFIERS = {
    "only": (0.943, 1.056, 1.488),
    "just": (0.468, 0.622, 1.134),
    "also": (0.155, 0.618, 0.763),
    "still": (0.292, 0.505, 0.815),
    "really": (0.075, 0.159, 0.619)
}
ADVERBS = {
    "exactly": 0.472,
    "ever": 0.295,
    "either": 0.222,
    "merely": 0.607,
    "simply": 0.204,
    "already": 0.215
}


@lru_cache(maxsize=8192)
def noun(word):
    return word not in FUNCTION_WORDS and 'noun' in wordnet.parts_of_speech(word)


def equality(token, before):
    if not token.startswith(' '):
        return 0.029
    line = re.split(r'\n|\\n', before)[-1].rstrip()
    match = re.search(r'([\w$]+)$', line)
    if not match:
        return 0.026
    name = match[1]
    if re.search(r'\b(const|let|var)\s+[\w$]+$', line):
        return -0.575
    if match.start() and line[match.start()-1] == '.':
        return 0.0
    if name.isidentifier() and len(name) > 1:
        if re.fullmatch(r'\s*(?:\d+\s+)?[A-Za-z_$][\w$]*', line):
            return -0.394
        return -0.095
    code = re.search(r'\b(import|def|const|let|var)\b|;|\{', before)
    if name.isidentifier() and code:
        return -0.07
    return 0.026


def response(token, before):
    initial = not before or before.endswith('<|endoftext|>')
    word = token.strip().lower()
    # Join Latin word fragments, so N + ur can still be recognized as Nur.
    if word.isascii() and word.isalpha() and token[0].isalpha():
        tail = re.search(r'[a-zA-Z]+$', before + token)
        if tail:
            word, before = tail[0].lower(), before[:tail.start()]
    if word == 'nur':
        return 1.584
    if word in {'tylko', 'только', 'apenas', 'chỉ', 'solo', 'só',
                'sólo', 'soltanto', 'seulement'}:
        return 1.088
    if word in {'只', '仅', '僅', '只是', '只有', '至少', '刚', '剛', '挺'}:
        return 0.607
    if word in {'还', '還', '再', '也'}:
        return 0.313
    if word in ADVERBS:
        return ADVERBS[word]
    if word == '±':
        return 0.573
    if word in {':=', '<-'}:
        return -0.399
    if word == '=':
        return equality(token, before)
    connectors = {'of', 'as', 'than', 'least', 'most', 'to', 'and'}
    if word not in MODIFIERS and word not in connectors:
        return -0.187 if initial and word.isalpha() else -0.001
    match = re.search(r'([a-z]+)\s*$', before.lower())
    previous = match[1] if match else ''
    if word in MODIFIERS:
        ordinary, nominal, pronominal = MODIFIERS[word]
        determiners = {'the', 'a', 'an', 'his', 'her', 'your', 'its'}
        if word == 'only' and previous in determiners:
            return -0.163
        if previous in SUBJECTS:
            return pronominal
        if noun(previous):
            return nominal
        if word == 'only' and previous in AUXILIARIES:
            return 1.345
        if word == 'just' and previous in {'not', 'than'}:
            return 1.038
        return ordinary
    if word in {'least', 'most'}:
        if previous == 'at':
            return 1.414 if word == 'least' else 1.138
        return -0.001
    if word == 'than':
        if previous == 'rather':
            return -0.09
        return 0.316 if previous in {'less', 'greater', 'other'} else 0.613
    if word == 'of':
        if previous in {'one', 'each', 'any', 'either', 'which', 'total'}:
            return 1.121
        quantities = {'some', 'several', 'both', 'many', 'few',
                      'two', 'three', 'four'}
        if previous in quantities:
            return 0.435
        return 0.774 if previous == 'none' else 0.012
    if word == 'as':
        if previous == 'same':
            return 0.661
        if previous in {'well', 'long', 'soon', 'far'}:
            return 0.199
        phrase = re.search(r'\bas ((?:[a-z]+ ){0,3}[a-z]+)\s*$', before.lower())
        if phrase:
            parts, pos = phrase[1].split(), wordnet.parts_of_speech(previous)
            descriptive = bool({'adjective', 'adverb'} & pos)
            degree = descriptive and not set(parts) & FUNCTION_WORDS
            if degree or parts[0] in {'much', 'many', 'few', 'little'}:
                return 1.524
        return 0.034
    comparisons = {'up', 'similar', 'identical', 'superior',
                   'opposite', 'limited', 'comparable'}
    if word == 'to' and previous in comparisons:
        return 0.507
    if word == 'and' and previous in {'to', 'with', 'into', 'through', 'before', 'in'}:
        return 0.527
    return -0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, (before + token)[-160:]), response(token, before)

programs.haiku:
"""Component layers.1.mlp.down_proj:5190, read as a word detector.

What it does, in plain terms:
- It fires on the word "only" and its equivalents ("just", "merely", "solely", "least" as in
  "at least", and "only" in other languages: nur, solo, apenas, tylko, только, seulement, 只, 仅).
  It is strongest when "only" modifies a verb or subject ("it only took coins", "I only had
  to walk"), and near zero in "the only one", a noun modifier.
- It fires weakly on additive/scalar words: "also", "still", "already", "really", "ever",
  "exactly", "than" in comparatives ("longer than", "better than").
- It fires on "of" after a selecting word ("one of", "any of", "each of", "either of",
  "which of", "total of"), and on "as" in "not ... as" comparisons.
- It is negative on code assignment operators ("=" in "const x =" most of all, ":=", "<-")
  and on a run of middle dots "··", and slightly negative on "of" after role nouns
  ("member of", "Director of").

Everything else predicts 0. It needs no state beyond the current line and a few tokens back.
"""

READS = ()

# "only"-type focus words, in English and other languages.
ONLY_WORDS = {
    " only", " Only", "only", "Only", " just", " Just", "just", "-only", " merely", " solely",
    " simply", " purely", " least", " exactly", " Nur", " nur", " solo", " sólo", " apenas",
    " tylko", " только", " лишь", " seulement", "只", "只有", "仅", "至少", "刚", "剛", "chỉ",
    "挺", "merely", "solo",
}
# Additive / scalar adverbs that weakly raise the component.
ALSO_WORDS = {
    " also", " still", " already", " really", " ever", " never", " certainly", " typically",
    " indeed", " longer", " als", " schon", " erst", "还", "再", "又",
}
# Selecting words that, before "of", leave "of" strongly positive ("one of these").
SELECTORS = {" one", " One", "One", " any", " each", " either", " neither", " which", " total",
             " none"}
# Role nouns whose following "of" is mildly negative ("member of", "Director of").
ROLES = {" member", " director", " Director", " president"}


def current_line(tokens):
    """The text of the line the last token is on, before that token."""
    words = []
    for token in reversed(tokens[:-1]):
        if "\n" in token:
            break
        words.append(token)
    return "".join(reversed(words))


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    token = tokens[-1]
    previous = tokens[-2] if len(tokens) > 1 else ""
    if token in ONLY_WORDS:
        # "the only one" is a noun modifier, where the component is off.
        return None, (0.0 if previous in {" the", " The"} else 1.0)
    if token == " than":
        return None, 0.5
    if token in ALSO_WORDS:
        return None, 0.35
    if token == " of":
        if previous in SELECTORS:
            return None, 1.2
        if previous in ROLES:
            return None, -0.3
        return None, 0.0
    if token == " as" and "not" in [t.strip() for t in tokens[-5:-1]]:
        return None, 1.0
    if token == " =":
        first = current_line(tokens).split()
        declared = bool(first) and first[0] in {"const", "let", "var"}
        return None, -0.5 if declared else -0.15
    if token == " :=":
        return None, -0.35
    if token == " <-":
        return None, -0.4
    if token == "··":
        return None, -1.5
    return None, 0.0

"""Draft 5: place, direction and scope words.

Strong: a directional particle (up-, down-, under-, over-, on-, off-, in-, out-, above-) or a
scope word (world-, state-, nation-) joined to a place noun, e.g. underground, downstream,
offshore, onboard, overseas, indoors, worldwide, statewide. Medium: listed place, direction
and time adverbs (overall, instead, online, outside, inside, opposite). Weak: nouns and
adverbs of extent or place (earth, front, campus, abroad, elsewhere, shore).
Phrases: 'over'/'day' after 'all' (all over, all day) and 'front'/'place' after 'in' (in front).
A special case: the 'reg' of down-regulation / up-regulation is strongly negative.
Levels: compound 2.0, medium 1.0, weak 0.4, phrases 2.5 / 1.8, down/up-regulation -5.0.
"""
READS = ()

PARTICLES = ("up", "down", "under", "over", "on", "off", "in", "out", "above", "world", "state", "nation")
PLACE_NOUNS = ("ground", "stream", "town", "side", "stairs", "water", "sea", "seas", "shore", "board",
               "hill", "land", "door", "doors", "screen", "site", "stage", "head", "night", "all",
               "world", "field", "foot", "draft", "fishing", "state", "wide")
MEDIUM = set("""overall instead opposite online offline outside inside aboard atop nearby underneath
outright upright ashore""".split())
WEAK = set("""earth front campus abroad elsewhere shore nowhere vitro vivo midnight anytime beforehand
overnight""".split())

def current_word(prefix):
    """The letters of the word the current token ends, e.g. 'underground'."""
    pieces = []
    docs = prefix.document_ids
    for i in range(len(prefix.token_strings) - 1, -1, -1):
        if docs[i] != docs[-1]:
            break
        s = prefix.token_strings[i]
        pieces.append(s)
        if s[:1].isspace() or not s.strip():
            break
    return "".join(c for c in "".join(reversed(pieces)) if c.isalpha()).lower()

def is_compound(word):
    return any(word.startswith(p) and word[len(p):] in PLACE_NOUNS for p in PARTICLES)

def step(carry, prefix, upstream):
    word = current_word(prefix)
    cur = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in ("downreg", "upreg"):
        value = -5.0
    elif word in MEDIUM:
        value = 1.0
    elif is_compound(word):
        value = 2.0
    elif word in WEAK:
        value = 0.4
    elif prev == "all" and cur in ("over", "day"):
        value = 2.5
    elif prev == "in" and cur in ("front", "place"):
        value = 1.8
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A current-token approximation of a foreign grammatical-piece detector.

Japanese case particles receive the largest values. Other kana, Korean
case particles and endings, and Chinese possessive particles receive
smaller values. Scripts and whitespace supply fallback estimates.
Incomplete UTF-8 tokens are assigned a script when their bytes permit it.
The numbers are fitted category means; no token IDs or model weights are used.
This does not attempt to recover lexical or contextual variation.
"""
import regex
from functools import lru_cache

READS = ()

# Genitive, dative, object, and directional particles.
JAPANESE_CASE = set('のにをへ')
JAPANESE_COMMON_PARTICLES = {'は', 'で', 'も', 'まで', 'にも', 'には'}
JAPANESE_PARTICLES = set('がではへともや') | {
    'から', 'まで', 'より', 'など', 'だけ', 'こそ', 'ほど',
    'さえ', 'でも', 'しか', 'ので', 'には', 'では', 'にも',
}
JAPANESE_GRAMMATICAL_FORMS = {
    'する', 'した', 'して', 'している', 'してい', 'していた',
    'され', 'された', 'される', 'されて', 'されている',
    'いる', 'いた', 'ある', 'あった', 'なる', 'なった',
    'ない', 'なく', 'なか', 'でき', 'できる', 'です', 'でした',
    'ます', 'ました', 'ません', 'という', 'として', 'について',
}
KOREAN_CASE = {'의', '을', '를', '에', '에서', '에게', '으로', '로'}
KOREAN_PARTICLES = {'은', '는', '이', '가', '도', '와', '과', '만', '부터', '까지'}
KOREAN_ENDINGS = {
    '다', '고', '며', '면', '서', '하는', '하고', '하여', '하면',
    '한다', '했다', '되는', '되고', '니다', '습니다', '입니다',
    '있는', '있다', '없는', '한다', '이나', '이라', '하게', '하기',
    '지만', '거나', '도록', '할', '된', '될', '됨',
}
CHINESE_STRUCTURAL = {'的', '之'}
CHINESE_FUNCTION = {
    '了', '着', '著', '过', '過', '是', '在', '于', '於', '为', '為',
    '不', '地', '得', '将', '將', '把', '被', '让', '讓', '与', '與', '和', '而', '也',
    '就', '都', '给', '給', '以', '由', '所', '及', '或', '但',
}
INDONESIAN_GRAMMAR = {'yang', 'meng'}
ARABIC_RELATIVES = {'الذي', 'التي', 'الذين', 'اللاتي', 'اللائي', 'اللذان', 'اللتان'}
VIETNAMESE_TENSE = {'đang', 'đã', 'sẽ'}

@lru_cache(maxsize=65536)
def activation_for_token(text, raw):
    # Pad missing continuation bytes just to guess the Unicode script.
    if "\ufffd" in text and raw:
        padded = (raw.strip() + b"\x81" * 3).decode("utf-8", "ignore")
        if regex.search(r"\p{Script=Hangul}", padded):
            return 0.522
        if regex.search(r"\p{Script=Hiragana}", padded):
            return 0.916
        if regex.search(r"\p{Script=Han}", padded):
            return 0.079
    s = text.strip()
    if s.startswith('<|'):
        return -0.071
    if not s:
        return -0.010
    if all(regex.match(r'\p{M}', c) for c in s):
        return 0.038
    if s in JAPANESE_CASE:
        return 2.742
    if s in JAPANESE_COMMON_PARTICLES:
        return 2.383
    if s in JAPANESE_PARTICLES:
        return 1.860
    if s in JAPANESE_GRAMMATICAL_FORMS:
        return 1.512
    # A token may contain a case particle and the start of its next word.
    if len(s) > 1 and s[0] in JAPANESE_CASE:
        if regex.fullmatch(r'[\p{Script=Hiragana}\p{Script=Han}]+', s):
            return 1.623
    hira = regex.search(r'\p{Script=Hiragana}', s)
    kata = regex.search(r'\p{Script=Katakana}', s)
    han = regex.search(r'\p{Script=Han}', s)
    if hira:
        if han:
            return 1.233 if s[-1] in 'のにをがではともへ' else 0.815
        return 1.277
    if kata:
        return 0.538 if len(s) == 1 else 0.265
    # Korean object markers; then genitive/locative and other case markers.
    if s in {'을', '를'}:
        return 2.393
    if s in {'의', '에'}:
        return 1.976
    if s in KOREAN_CASE:
        return 1.525
    if s in KOREAN_PARTICLES:
        return 0.863 if text[0].isspace() else 1.248
    if s in KOREAN_ENDINGS:
        return 0.789
    if regex.search(r'\p{Script=Hangul}', s):
        return 0.397 if text[0].isspace() else 0.302
    if s in CHINESE_STRUCTURAL:
        return 1.010
    if s in CHINESE_FUNCTION:
        return 0.264
