        elif name == "__name":
            value = -1.9
        elif name == "__main":
            value = -4.3
        elif name.startswith("__"):
            value = -2.6
        elif "__" in name:
            value = -3.0
        else:
            value = -3.4
    elif "__" in token and token.count("_") == 2:
        value = -1.0 if token.endswith("__/") else -0.45
    elif token.strip() == "_":
        value = -0.16
    elif "—" in token and token.count("—") == 1:
        if token[0].isspace():
            value = 0.07
        elif token == "—" and tail[-1:].isspace():
