@lru_cache(maxsize=16384)
def token_value(s):
    s = s.strip()
    if not s:
        return -0.002
    if s and set(s) == {'·'} and len(s) >= 2:
        return -1.55
    if s[-1] in '想相像象':
        v = 1.55 if s[-1] in '想相' else 3.1
        if len(s) > 1:
            v *= 0.65
        if s.startswith('不'):
            v += 1.8
        return v
    if s[-1] in '向乡鄉響':
        return 0.4 if len(s) == 1 else 0.2
    if '상' in s:
        return 2.7 if s == '상' else (1.1 if s.startswith('상') else 0.15)
    if s == '향':
        return 0.45
    # Strip Vietnamese tone/vowel marks, without a learned word table.
    plain = ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                    if unicodedata.category(c) != 'Mn').replace('ư', 'u')
    if plain.endswith('uong') and not s.isascii():
        if plain == 'tuong':
            if 'ươ' in s:
                return 5.3
            if 'ướ' in s:
                return 2.1
            if 'ưở' in s:
                return 1.2
            return 3.5
        return 1.6
    if any(c in s for c in '想相像象'):
        return 0.12
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, b'', '')
    _, position, tail, previous = carry
    raw = prefix.token_bytes[-1]
