            v = 6.2
        elif word.endswith(('jiang', 'qiang')):
            v = 0.9
        elif word.endswith('liang'):
            v = 3.7
        elif word.endswith('iang'):
            v = 3.0
        elif word.endswith('uong'):
            v = 5.1
        elif word.endswith('yang'):
            v = 1.5
        elif word.endswith('uang'):
