"""A partial Chinese activity-reporting feature.

Dictionary verbs get a small response, larger for establishing, building,
launching or starting things. Completion, cumulative totals and recent reporting
markers increase it. Research/development and initial ``Title:`` have their own
responses. 出/成 get a resultative boost after a dictionary verb.
This omits idiosyncratic token offsets and most contextual variation.
"""
from functools import lru_cache
import re
import regex
import cedict

READS = ()

# Familiar kinds of action, identified in CC-CEDICT's English infinitives.
MEANINGS = (
    (0.229, 'establish found'),
    (0.181, 'construct build create'),
    (0.133, 'launch release publish print issue distribute'),
    (0.091, 'start begin open initiate'),
)
MEANINGS = tuple((weight, frozenset(words.split()))
                 for weight, words in MEANINGS)

COMPLETION = frozenset('先后 已 已有 已经 成功 新 新开 曾 曾经 现已'.split())
TOTAL = frozenset('一共 共 共有 共计 总共 总计 累计'.split())
TIME = frozenset('今年 去年 年 日 日前 月 每天 每年 每月 现 现已 目前 近日'.split())
SCOPE = frozenset('全县 全国 全市 全省'.split())
CUES = COMPLETION | TOTAL | TIME | SCOPE

@lru_cache(maxsize=32768)
def word(s):
    if not regex.fullmatch(r'\p{Script=Han}+', s):
        return 0.0, False, False, ''
    glosses = cedict.glosses(s)
    if not glosses and len(s) > 1 and s[-1] in '了着过':
        glosses = cedict.glosses(s[:-1])
    roots = set()
    for gloss in glosses:
        gloss = re.sub(r'^\([^)]*\) ', '', gloss)
        roots.update(re.findall(r'(?:^|; )to ([a-z]+)', gloss))
    verb = bool(roots)
    value = -0.007
    if verb:
        value += 0.112
        if len(s) == 1:
            value -= 0.118
        elif len(s) > 2:
            value += 0.067
        value += sum(w for w, meanings in MEANINGS if roots & meanings)
    return value, verb, True, ' '.join(glosses)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, age, position = '', 99, 0
    else:
        _, previous, age, position = carry
    s = prefix.token_strings[-1].strip()
    base, verb, han, gloss = word(s)
    value = -0.001 + base
    if s in COMPLETION:
        value += 0.313
    if s in TOTAL:
        value += 0.909
    if s in TIME:
        value += 0.035
    if s in SCOPE:
        value += 0.393
    if verb and age < 4:
        value += 0.161
    if verb and previous in CUES:
        value += 0.314
    if han and previous in CUES:
        value += 0.153
    # Already/newly + a verb, but not lexicalized nouns such as 新闻 (news).
    aspect = (len(s) > 1 and s[0] in '已新' and word(s[1:])[1]
              and (s[0] == '已' or not gloss or verb))
    if aspect or s == '现有':
        value += 0.654
    if 'research and development' in gloss:
        value += 1.303
    if s in ('累计', '先后'):
        value += 1.269
    if s in ('出', '成') and word(previous)[1]:
        value += 0.288
    if position == 1 and previous == 'Title' and s == ':':
        value += 3.435
    age = 0 if s in CUES else age + 1
    return (doc, s, age, position + 1), float(value)

