"""Layer-1 MLP down_proj component 5197: "complement-taking noun" detector.

What it responds to: abstract head nouns that take a complement, such as
"ability (to)", "option (to)", "chance (to)", "fact (that)", "plurality/variety/
majority (of)", "possibility (of)". It fires a little on the noun itself and
strongly on the complement word that follows it (" of", " to", " that", and the
Romance " de"/" di"). A second, odd, small effect: a bare space token directly
after " a" (the tokenizer's split before a digit, as in "a 2D") pushes it negative.

Predicts a fixed activation for each such token; 0 everywhere else.
"""

READS = ()

# Abstract nouns that normally take an "of", "to" or "that" complement.
COMPLEMENT_NOUNS = {
    " ability", " chance", " opportunity", " possibility", " option", " effort",
    " fact", " majority", " plurality", " variety", " potential", " exception",
    " wrong", " impression", " intention", " instant", " feeling", " idea",
    " choice", " decision", " aim", " couple", " illusion", " typo",
}
# The complement words themselves.
COMPLEMENT_WORDS = {" of", " to", " that", " de", " di"}

NOUN_VALUE = 0.39        # the noun itself
COMPLEMENT_VALUE = 0.84  # the "of/to/that" right after such a noun
DE_VALUE = 0.14          # Romance "de/di" after another word
BARE_SPACE_AFTER_A = -0.95  # a lone space token right after " a"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        before = ""
    else:
        before = prefix.token_strings[-2]

    if token in COMPLEMENT_NOUNS:
        value = NOUN_VALUE
    elif token in COMPLEMENT_WORDS and before in COMPLEMENT_NOUNS:
        value = COMPLEMENT_VALUE
    elif token in (" de", " di"):
        value = DE_VALUE
    elif token == " " and before == " a":
        value = BARE_SPACE_AFTER_A
    else:
        value = 0.0
    return carry, float(value)

