"""Approximate a spelling-sensitive signal, not general negative sentiment.

It is positive on WRONG/INCORRECT and on several silent-WR word stems,
especially when WR is split between tokens. It is negative on short,
fragmented R + high-vowel syllables (RIS, RIG, RUS, etc.), including
transliterated Greek/Cyrillic text. Most other tokens get zero.
Only the unfinished word and previous token are carried between steps.
"""
import re
from functools import lru_cache

import regex
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=65536)
def romanize(text):
    return anyascii(text).lower()


def response(word_before, previous, token):
    text = romanize(token)
    old = romanize(previous).strip()
    word = text.strip('_ .\t\r\n')
    value = 0.0

    if word.startswith('wrong'):
        value = 4.9
        if any(c.isupper() for c in token):
            value += 1.0
        if old in ('is', 'are', 'am', 'was', 'were'):
            value -= 1.8
    elif word.startswith('incorrect'):
        value = 1.4 if word == 'incorrect' else 0.3
    elif word.startswith('wrest'):
        value = 6.0 if word == 'wrest' else 1.4
    elif word in ('writ', 'wrist'):
        value = 1.7
    elif word.startswith('wright'):
        value = 1.2
    elif word == 'wr':
        value = 0.3
    elif word.startswith('wrath'):
        value = 0.7

    match = re.match('[a-z]+', text.lstrip())
    head = match[0] if match else ''
    joined = bool(text[:1].isalpha() and word_before)
    if joined:
        if head in ('write', 'writing', 'writers'):
            value += 0.4
        if word_before.endswith('w') and head.startswith('r'):
            value += 1.3 if len(head) <= 4 else 0.5
            # The fragments completing writ, wrest and wry are especially strong.
            if head in ('rit', 'rest', 'ry'):
                value += 5.7
            if head == 'right':
                value += 2.5
        if word_before.endswith('aw') and head == 'ry':
            value += 1.7
        if word_before.endswith(('pr', 'thr')) and head == 'ong':
            value += 5.1

    # Look at just the newly extended syllable around the token boundary.
    left = word_before[-5:] if joined else ''
    fragment = left + head
    boundary = len(left)
    for match in re.finditer('r[iuy]', fragment):
        r = match.start()
        if r + 1 < boundary - 1 or r > boundary + 2:
            continue
        ending = fragment[r + 2:]
        if len(ending) > 1 and ending[1:] not in ('e', 'er', 'o', 'y', 'ue'):
            continue
        before = fragment[r - 1:r] if r else ''
        if before and before in 'aeiouw':
            continue
        if not boundary and (len(head) > 3 or r > 1):
            continue
        after = fragment[r + 2:r + 3]
        if after in ('s', 'z'):
            value -= 1.0
        if after in ('g', 'c', 'k'):
            value -= 0.2
        if after in ('s', 'z', 'g') and before in ('b', 'c', 'd', 'f', 'g', 'k', 'r'):
            value -= 1.2
        if before == 'g':
            value -= 0.4
        if regex.search(r'\p{Script=Greek}', token + previous):
            value -= 2.3
        if 'ř' in (token + previous).lower():
            value -= 0.5
        break

    if old == 'wrong' and word == 'with':
        value += 2.8
    if old == 'wrong' and head == 'fully':
        value += 7.2

    tail = re.search('[a-z]+$', text)
    next_word = ''
    if tail:
        next_word = (word_before + text)[-24:] if text.isalpha() else tail[0][-24:]
    return next_word, value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        word, previous = '', ''
    else:
        _, word, previous = carry
    token = prefix.token_strings[-1]
    word, value = response(word, previous, token)
    return (document, word, token), value

