MODAL_HAVE = {
    'to': 0.5, 'can': 0.6, 'will': 1.0, 'shall': 0.4,
    'would': 0.0, 'could': -0.7, 'should': 0.4,
    'must': 0.8, 'may': 0.6, 'might': 0.4,
