                   'possui', 'teve', 'tiveram', 'tenha', 'tenham'}
FRENCH_HAVE = {'avoir', 'avait', 'avaient', 'avais', 'avons', 'avez', 'ont'}
GERMANIC_HAVE = {'haben', 'habe', 'hast', 'hat', 'hatte', 'hatten',
