programs.haiku:
"""Component layers.1.mlp.down_proj:5199: the "have" feature.

This component fires on the verb "have" (have, has, had, hath, having) when it is used
as a verb with a person or thing as subject: "we have", "I had", "it has", "he hath".
It is strongest right after a personal pronoun or a contracted subject ("I've had"),
and strongest of all after a negation ("don't have"). It is weak when a noun phrase is
the subject ("the position has"), and slightly negative for a question-initial "Have you".
On every other token it stays near zero.

The program has no state beyond the previous token, and it reads only the newest
token and the one before it.
"""

READS = ()

HAVE_WORDS = {"have", "has", "had", "hath", "having"}
PRONOUNS = {"i", "you", "he", "she", "it", "we", "they", "who", "which"}
CONTRACTED_SUBJECT = {"'ve", "’ve", "'d", "’d"}
NEGATIONS = {"not", "dont", "don", "’t", "n't", "didnt", "doesnt", "never"}


def step(carry, prefix, upstream):
    # Start of a document: the previous token belongs to another document.
    doc = prefix.document_ids
    if len(doc) < 2 or doc[-2] != doc[-1]:
        prev = ""
    else:
        prev = prefix.token_strings[-2].strip().lower()
    word = prefix.token_strings[-1].strip().lower()
    if word not in HAVE_WORDS:
        return carry, 0.0
    if prev in NEGATIONS:
        value = 3.0
    elif prev in PRONOUNS or prev in CONTRACTED_SUBJECT:
        value = 2.0
    elif prev in ("", ".", "?", "!", '"', "\n", "“", "“"):
        value = -0.5
    else:
        value = 0.5
    return carry, value

