"""Mostly a detector of masculine third-person pronouns and possessives.

Recent function words estimate the language, separating French 'il' (he) from
Italian 'il' (the), German 'er' (he) from Scandinavian 'er' (is), and French
'son' (his) from English 'son'. The response depends on the grammatical form.
English pronouns are slightly weaker after a recent strong response. Smaller
responses cover some feminine forms and German 'der'. This is lexical, not
antecedent resolution: a word's first token can fire before the word finishes.
"""
import math

READS = ()

# Distinctive function words provide a small, fading language tally.
CUES = {
    'en': 'the and of to is was were with for that which',
    'fr': 'le les des du une est dans au aux avec pour sur mais qui pas nous vous leur',
    'it': 'di che del della delle degli gli dei una sono nel nella per non con alla',
    'de': 'der die das ein eine und ist nicht mit auf zu von den dem des sich',
    'es': 'el los las una del que por para con pero como sus esta este',
    'pt': 'o os um uma dos das não pelo pela ao aos é são seu seus com em da na',
    'nl': 'het een van zijn niet voor met ook wordt door deze als',
    'sc': 'och att det som på av är og ikke til den',
    'tr': 'bir bu ve için ile olarak değil daha çok gibi ama ben',
    'hu': 'az egy és hogy nem van',
}
LANGS = tuple(CUES)
WORD_LANGS = {}
for language, words in CUES.items():
    for word in words.split():
        WORD_LANGS.setdefault(word, []).append(LANGS.index(language))

# These are closed-class grammatical forms, not a token-id lookup table.
FORMS = {
    'fr': {'il': -7.8, 'ils': -1.0, 'son': -3.4, 'sa': -4.4,
           'ses': -5.5, 'lui': -2.0, 'celui': -0.6, 'elle': -0.8},
    'de': {'der': -0.8, 'er': -6.1, 'ihm': -5.7, 'ihn': -3.9, 'sein': -2.9,
           'seine': -6.2, 'seiner': -5.3, 'seinem': -4.0,
           'seinen': -3.8, 'seines': -4.5},
    'es': {'él': -5.5, 'su': -4.2, 'sus': -4.2},
    'it': {'sua': -5.8, 'sue': -7.0, 'suo': -2.9, 'suoi': -3.0,
           'gli': -1.5, 'lui': -2.0},
    'pt': {'ele': -5.0, 'sua': -3.5, 'seu': -0.8, 'seus': -1.7},
    'nl': {'hij': -4.0, 'hem': -4.0, 'zijn': -2.6},
    'sc': {'han': -5.8, 'hans': -4.0, 'dess': -2.2},
}
RUSSIAN = {'он': -3.6, 'его': -4.0, 'него': -3.8,
           'нем': -3.5, 'нём': -3.5, 'ему': -3.5}
OTHER = {'他': -2.8, '他的': -2.2, '他是': -1.6, '其': -1.2,
         '그': -1.2, 'أنه': -4.9, 'هو': -0.8}
ENGLISH = {'he': -3.5, 'him': -3.2, 'his': -3.45,
           'himself': -1.0, 'she': -0.42}
FALLBACK = {'il': -2.8, 'er': -1.5, 'su': -1.4, 'son': -0.8}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        scores, previous, age = [0.0] * len(LANGS), '', 1000
    else:
        _, scores, previous, age = carry
    token = prefix.token_strings[-1]
    bare = token.strip()
    word = bare.lstrip("'’.-").lower()
    boundary = (not previous or not previous[-1:].isalpha()
                or token[:1].isspace() or bare[:1] in "'’.-")
    best = max(range(len(scores)), key=scores.__getitem__)
    language = LANGS[best] if scores[best] > 0.25 else 'unknown'
    sentence = (not previous or '\n' in previous
                or previous.rstrip(" \"'”’)]}").endswith(('.', '!', '?')))
    value = 0.0
    if word in OTHER:
        value = OTHER[word]
    elif boundary:
        if word in RUSSIAN:
            value = RUSSIAN[word]
        elif word in ENGLISH and language in ('en', 'unknown'):
            value = ENGLISH[word]
            if word in ('he', 'him', 'his'):
                value += 0.45 * math.exp(-age / 35.0)
                if bare[:1].isupper():
                    if word == 'he':
                        value = (-3.4 if sentence else -1.3)
                        value += 0.3 * math.exp(-age / 35.0)
                    elif word == 'him':
                        value = -2.2
                if word == 'he' and bare[:1].isupper() and not token[:1].isspace():
                    value *= 0.8
                if bare.startswith(('.', '-')):
                    value *= 0.5
                if bare.isupper():
                    value *= 0.6
        elif word == 'il' and bare.startswith(("'", '’', '-')):
            value = -9.0 if bare.startswith('’') else -7.8
            if bare.startswith('-'):
                value = -6.1
        else:
            value = FORMS.get(language, {}).get(word, 0.0)
            if language == 'unknown':
                value = FALLBACK.get(word, 0.0)
            if language == 'de' and word == 'er' and bare[:1].isupper():
                value = -5.8 if sentence else -2.0
            if language == 'fr' and word == 'il' and bare[:1].isupper():
                value *= 0.9
            if bare.isupper():
                value = 0.0
    age = 0 if value < -1.5 else age + 1
    scores = [x * 0.985 for x in scores]
    if boundary:
        for i in WORD_LANGS.get(word, ()):
            scores[i] += 1.0
    return (doc, scores, token, age), value

"""Approximate document-opening cues, not ordinary running text.

The colon after an opening `Title` is strongly positive. An opening `public`
(Java's access keyword) is positive too. Punctuation-only opening tokens are negative;
ASCII-letter tokens ending in -ed, -ing or -s have small positive average responses.
These coarse opening classes leave the component's other variations at zero.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is not None and carry[0] == document:
        value = 2.75 if carry[1] and token == ':' else 0.0
        return (document, False), value

    word = token.strip()
    if token == 'Title':
        value = -0.298
    elif token == 'public':
        value = 1.615
    elif word and all(unicodedata.category(c).startswith('P') for c in word):
        value = -0.29
    elif word.isascii() and word.isalpha():
        word = word.lower()
        if len(word) > 4 and word.endswith('ed'):
            value = 0.24
        elif len(word) > 5 and word.endswith('ing'):
            value = 0.15
        elif len(word) > 3 and word.endswith('s'):
            value = 0.13
        else:
            value = 0.0
    else:
        value = 0.0
    return (document, token == 'Title'), value

"""Spelling pulses for lh/nh and split accented-verb clitics.

A token completing lh or nh gets a positive pulse, especially when the
word so far matches a common Portuguese spelling. A weaker trace fades
through subsequent pieces of the same word. Whole-token digraphs have a
much smaller immediate response. This is only a spelling approximation.
"""
from wordfreq import top_n_list

READS = ()
PORTUGUESE_PREFIXES = {
    word[:end]
    for word in top_n_list('pt', 30000)
    if word.isalpha() and ('lh' in word or 'nh' in word)
    for end in range(1, len(word) + 1)
}
PRONOUNS = set('se me te lhe lhes nos vos lo la los las o a os as'.split())
ACUTE_VOWELS = set('áéí')


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        old, lateral, nasal = '', 0.0, 0.0
    else:
        _, old, lateral, nasal = carry
    text = prefix.token_strings[-1].lower()
    previous, first = old[-1:], text[:1]
    joined = previous.isalpha() and first.isalpha()
    word = old + text if joined else text.strip()
    portuguese = word in PORTUGUESE_PREFIXES

    split_lh = previous == 'l' and first == 'h'
    split_nh = previous == 'n' and first == 'h'
    inside_lh, inside_nh = 'lh' in text, 'nh' in text
    lateral = lateral if joined and not (split_lh or inside_lh) else 0.0
    nasal = nasal if joined and not (split_nh or inside_nh) else 0.0
    value = lateral + nasal
    if split_lh:
        value += 2.893 if portuguese else 0.481
    if split_nh:
        value += 1.348 if portuguese else 0.085
    if portuguese:
        value += 0.168 * inside_lh + 0.111 * inside_nh

    if text == '-' and previous in ACUTE_VOWELS:
        value += 1.472
    if (old.endswith('-') and old[-2:-1] in ACUTE_VOWELS
            and text in PRONOUNS):
        value += 2.645
    if previous.isalpha() and text.startswith('-') and text[1:] in PRONOUNS:
        value += 0.093

    if split_lh or inside_lh:
        lateral = 1.326 if portuguese else 0.101
    else:
        lateral *= 0.55
    if split_nh or inside_nh:
        nasal = 0.516 if portuguese else 0.007
    else:
        nasal *= 0.55
    if text.strip().isalpha():
        old = word[-48:]
    elif text == '-':
        old += '-'
    else:
        old, lateral, nasal = '', 0.0, 0.0
    return (doc, old, lateral, nasal), float(value)

