"""Layer 1 MLP down_proj, component 5204: a weak, sparse negative detector for words that
sit inside a compound or premodifier phrase, the place where the next word is likely to be
a head noun ("award-winning", "high efficiency", "gluten free", "17th-century").

Three readable cues, each giving a small negative value (the component is negative there):
  1. a hyphen-joined English word ("-free", "-winning", "-century", "-dependent");
  2. a word right after a degree or size adjective ("high", "low", "slow", "heavy", ...);
  3. a participle or adjective ending piece ("ed", "ing", "ored", "ting", ...).
Everything else predicts 0. The activations are mostly near 0 with rare large negative
spikes, so these cues capture only a little of the variance (the rest is context-specific).
"""

READS = ()

DEGREE_OR_SIZE = {"high", "low", "higher", "lower", "slow", "fast", "heavy", "long", "large",
                  "small", "short", "multi", "single", "double"}
PARTICIPLE_PIECES = {"ed", "ing", "ored", "ted", "ised", "ized", "ailed", "ting", "ged"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if cur.startswith("-") and len(cur) > 1:
        return None, -0.25
    if prev in DEGREE_OR_SIZE and cur.strip().isalpha():
        return None, -0.2
    if cur in PARTICIPLE_PIECES:
        return None, -0.25
    return None, 0.0

programs.sol:
"""Contrast familiar type/literal/operator spellings with identifier starts in code.

Types and Booleans are negative, especially in argument lists. Indented object
references, single-letter names and English function words get small positive
values. Conventional test-case and conversion/factory name prefixes are also
positive. Recent source punctuation gates most rules. Type penalties skip quoted
"string" labels and Rust attributes. These spelling/syntax rules deliberately
leave much token-specific variation unexplained.
"""
import re

READS = ()
TYPES = set('int float double char bool boolean string str void integer object '
            'struct array'.split())
FUNCTION_WORDS = set(
    'a an the of to from by for in on at with without into through over under '
    'between before after as than it its they them their he him his she her '
    'we us our you your i me my this that these those all any some no each '
    'every many more most other one two three first last next out up down'.split()
)
CODE = re.compile(
    r';|->|::|[{}]\s*["\n]|[)\w]\s*\{'
    r'|\b(?:def|function|class)\s+\w+|\bimport\s+\w+'
    r'|\b(?:var|let|const)\s+\w+\s*='
)
WORD = re.compile(r'([.(,=</$]*)([A-Za-z_]+)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = history + token
    state = (doc, text[-256:])
    code = bool(CODE.search(text[-240:]))
    line = re.split(r'\n|\\n', history)[-1]
    line = re.sub(r'^\s*\d+\s*\t', '', line)
    indented = bool(history) and not line.strip() and token[:1].isspace()
    tail = history.rstrip()
    comma, opening = tail.endswith(','), tail.endswith('(')
    match = WORD.fullmatch(token.strip())
    punct, word = match.groups() if match else ('', '')
    low = word.lower()
    argument = comma or opening or punct in {'(', ','}
    value = 0.0

    if low in TYPES:
        quoted = tail.endswith(('"', "'")) and low == 'string'
        if '#[' not in line and not quoted:
            if argument:
                value = -1.5 if punct else -1.0 if opening else -1.6
                if low in {'string', 'str'} and punct:
                    value = -2.5 if word[:1].isupper() else -1.35
                elif word[:1].isupper():
                    value *= 0.6
            elif code:
                value = (-0.6 if punct else
                         -0.5 if low in {'string', 'str'} else -0.28)
                if word[:1].isupper():
                    value *= 1.7
    elif low in {'true', 'false'}:
        local_code = bool(re.search(r'[=(\[{:;]|\breturn\b', line))
        if punct or local_code or (code and indented):
            value = -1.9 if comma else -1.2 if punct else -1.0
    elif code:
        if low in {'null', 'none', 'nil'}:
            value = -0.65 if argument else -0.15
        elif low in {'const', 'final', 'mut'}:
            value = -2.4 if comma else -1.35 if argument else -0.28
        elif low in {'private', 'protected'}:
            value = -0.8
        elif low in {'class', 'interface', 'enum'} and punct:
            value = -1.0
        elif low in {'extends', 'implements', 'throws'}:
            value = -0.7
        elif low in {'this', 'self'}:
            if punct:
                value = -0.4
            elif indented:
                value = 0.8 if low == 'this' else 0.55
            else:
                value = 0.05
        elif low == 'it' and indented:
            value = 2.1  # The usual JavaScript test-case introducer.
        elif low in {'to', 'of'} and punct == '.':
            value = 1.1  # Conversion/factory method-name beginnings.
        elif low in FUNCTION_WORDS:
            value = 0.35 if indented else 0.27 if punct in {'.', '('} else 0.03
        elif len(word) == 1:
            if indented:
                value = 0.3
            elif punct == '(':
                value = 0.2
            elif token[:1].isspace():
                value = 0.04
        elif not word:
            symbol = token.strip()
            if '+' in symbol and not any(c.isalpha() for c in symbol):
                value = -0.35 if token[:1].isspace() else -0.18
            elif symbol in {'==', '!=', '===', '!==', '<<', '>>'}:
                value = -0.3
            elif '$' in symbol and '\n' not in symbol:
                value = -1.2 if opening else -0.65 if comma else -0.15
            elif symbol in {'__(', '_('}:
                value = 1.3
    return state, value

"""A partial spelling-and-phrase explanation of this sparse component.

Negative responses cover Soviet/Su spellings, so-called, Social Security,
and several s/v junctions inside split words. Positive responses cover
su+av and technical v+s compounds, repeated acronym letters, and a few
Japanese/Korean syllable junctions. An opening 'Title:' has a large negative
response. These are training-derived local patterns, not a unified semantic
category; unrecognized positions predict zero. State resets per document.
"""
import re
from functools import lru_cache
import unicodedata

READS = ()

@lru_cache(maxsize=65536)
def letters(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.casefold())
                   if not unicodedata.combining(c))

def response(previous, token, second=False, context=""):
    history = letters(context or previous)
    p, s = letters(previous), letters(token)
    a, b = p.strip(), s.strip()
    value = 0.0
    if second and previous == 'Title' and token == ':':
        value -= 13.07
    if b.startswith('soviet'):
        value -= 4.66
    if b.startswith('совет'):
        value -= 2.00
        if token.lstrip().startswith('С'): value -= 2.49
    if token in ('苏', '蘇'):
        value -= 6.19
    elif '苏' in token or '蘇' in token:
        value -= 2.00
    if previous.endswith(('苏', '蘇')) and token in ('维', '維', '俄'):
        value -= 5.42
    if previous.endswith(('苏维', '蘇維', '维', '維')) and token == '埃':
        value -= 10.26
    # Common multiword expressions and a word-family continuation.
    if a == 'so' and b in ('-called', 'called', '-so'):
        value -= 4.20
    if a == 'social' and b == 'security':
        value -= 4.54
    if a.endswith('sub') and s.startswith('vers'):
        value -= 4.03
    # Token-boundary spelling junctions, rather than whole-word meanings.
    if b == 'sv': value -= 1.76
    if b == 'св': value -= 0.36
    if not token[:1].isspace():
        if p.endswith('s') and s.startswith('v') and len(s) <= 4:
            value -= 0.74
            if s.startswith('ve'): value -= 1.08
            if len(s) == 1: value -= 0.54
        if p.endswith('с') and (s == 'в' or s.startswith(('ве', 'ви', 'ві'))):
            value -= 1.73
        if (p.endswith(('sv', 'svs')) and s[:1] in 'ei'
                and not token.startswith('ě')):
            value -= 1.34
        if p.endswith('св') and s[:1] in 'еиы':
            value -= 0.79
        if history.endswith('сві') and s.startswith(('т', 'д')):
            value -= 2.72
        if history.endswith(('sov', 'сов')) and s.startswith(('ie', 'et', 'ет')):
            value -= 7.70
        if p.endswith('s') and s in ('u', 'ud', 'ue'):
            value -= 0.36
        if p.endswith('su') and s[:1] in 'ao':
            value += 1.00
            if s.startswith('av'): value += 3.12
        if (p.endswith('v') and not p.endswith(('ov', 'sv'))
                and s.startswith(('sock', 'sync', 'system', 'space'))):
            value += 2.45
        if history.endswith('sv') and token.startswith('ě'):
            value -= 5.17
        if history.endswith('св') and s.startswith('і'):
            value -= 3.60
        if p.endswith('s') and token.startswith('ū'):
            value -= 3.42
        if (previous.endswith(('S', 'V'))
                and re.fullmatch(r'([A-Z])\1{1,3}', token)):
            value += 1.07
