    if token == '··': value += 1.47
    if token in (' su', ' Su'): value -= 0.10
    if token in ('su', 'Su'): value -= 0.96
    if b in ('sud', 'sue'): value -= 0.58
    if previous.endswith('소') and token == '방': value -= 4.11
    if previous.endswith('스') and token == '러': value += 5.07
    if p.endswith('ス') and token == 'ム': value += 2.59
    return value

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position, context = '', 0, ''
    else:
        _, previous, position, context = carry
    token = prefix.token_strings[-1]
    value = response(previous, token, position == 1, context)
    state = (doc, token, position + 1, (context + token)[-12:])
    return state, float(value)

"""Emit negative activation for short LI spelling fragments, including splits.

LIT is especially strong; LIB, LIC and bare LI are weaker. Familiar longer
words and productive endings such as -ity are mostly excluded. Cyrillic and
Greek letters are romanized; katakana r is treated as l.
There are separate responses for light/lights, literal(s), github.com and a
document-initial Title: header. Everything else is zero.
"""
from functools import lru_cache
from anyascii import anyascii
import unicodedata

READS = ()

@lru_cache(maxsize=32768)
def spelling(text):
    out = []
    for ch in text:
        name = unicodedata.name(ch, '')
        alphabetic = any(x in name for x in ('LATIN', 'GREEK', 'CYRILLIC'))
        if ch.isascii() or alphabetic:
            out.append(anyascii(ch))
        elif 'KATAKANA' in name:
            out.append(anyascii(ch).replace('r', 'l'))
        else:
            out.append(' ')
    return ''.join(out).lower()

@lru_cache(maxsize=65536)
def response(last, text):
    p, s = spelling(last), spelling(text)
    word = s.strip(' \n\t_./-([\"')
    if text.strip() == 'ли':
        return -3.0 if text[:1].isspace() else -.3
    if word in ('light', 'lights'):
        if word.endswith('s'):
            return -2.8
        return -1.1 if text[:1].isspace() else -2.6
    if word.rstrip('s') == 'literal':
        return -3.3 if word.endswith('s') else -1.6
    if word == 'liter':
        return -.7
    split = False
    if word.startswith('li'):
        ending = word[1:]
    elif p.endswith('l') and s.startswith('i'):
        ending, split = s, True
    elif p == 'li' and s in ('t','d','s'):
        ending, split = 'i'+s, True
    elif word == 'slit':
        ending = 'it'
    else:
        return 0.0
    if text.endswith(('ité', 'ités', 'ità')):
        return 0.0
    if ending in ('it', 'ite'):
        value = -5.5
    elif ending in ('ith', 'itt'):
        value = -4.0
    elif ending in ('is', 'iss', 'ist', 'ists', 'id'):
        value = -3.5
    elif ending in ('ib', 'ig', 'ic', 'icht'):
        value = -1.3
    elif ending in ('i', 'im', 'iv', 'ik', 'iz', 'ich'):
        value = -1.3 if split else -.5
    elif split and ending in ('ight', 'ights', 'its', 'ites'):
        value = -4.5
    else:
        return 0.0
    if split and len(p.strip()) > 3:
        value *= .25
    if text[:1].isspace() and ending in ('ib', 'ic', 'ig'):
        value *= .6
    # Ordinary complete words are not short fragments of 'lis...'.
    if word.rstrip('s') == 'list' and text.isascii():
        value *= .05
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        last, count = '', 0
    else:
        _, last, count = carry
    text = prefix.token_strings[-1]
    value = response(last, text)
    if text == '.com' and last.strip().lstrip('"') in ('github','ithub'):
        value = -1.8
    if count == 1 and last == 'Title' and text == ':':
        value = -10.6
    return (doc, text, count+1), value

