"""Layer 1, MLP down-projection, component 5207: a spelled "l-i-t" detector.

What it responds to: the letters l-i-t (also l-i-b, l-i-g, l-i-s-t) when they spell the
start of light, lit, lib, list, literal, lithium, lid, and pieces that end in "-lit", "-lib",
"-lig" (polit, Milit). The sign is negative: the component goes down on these and is close
to zero everywhere else. It is a weak, sparse feature: most of its variance is in rare large
dips, and these rules catch only part of them.

Rules (the value is about the typical activation of each group):
  - a word-piece from FAMILY (" light", " lights", "lit", " Lith", "lib", "elib", " lid",
    "lis", "slit", "Literal", Russian "ли" and "лист"): -1.6
  - "it" right after a piece ending in "l" (the letters "li" split over two pieces): -0.8;
    any other piece starting with "i" right after a piece ending in "l": -0.2
  - a piece ending in "lit", "lib" or "lig" (up to 7 letters): -0.5
  - the bare piece "li": -0.3; any other piece starting with "li": -0.1
  - everything else: 0
"""

import re

READS = ()

FAMILY = {
    "lit", "lith", "lis", "lid", "lib", "light", "lights", "literal", "literals",
    "slit", "plit", "elib", "lithium", "ли", "лист",
}


def letters(text):
    return "".join(ch for ch in text.lower() if ch.isalpha())


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    piece = letters(prefix.token_strings[-1])
    before = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = letters(prefix.token_strings[-2])
    if word in FAMILY:
        value = -1.6
    elif piece.startswith("i") and before.endswith("l"):
        value = -0.8 if piece.startswith("it") else -0.2
    elif re.search(r"(lit|lib|lig)$", piece) and len(piece) <= 7:
        value = -0.5
    elif word == "li":
        value = -0.3
    elif piece.startswith("li"):
        value = -0.1
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A comparative-degree signal: 'the more', 'the larger', 'the larger the'.

WordNet supplies the adjective morphology. A comparative after 'the' gets a
positive response, larger at a clause opening. The next article, pronoun, or
possessive continues the response, also after an intervening adjective/adverb
in a more/less phrase. Small secondary rules cover Chinese '越' and emphatic 'the hell'.
All other positions get zero. Only a short text tail is retained.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
# These -er words have adjective stems but are not comparative inflections.
NON_COMPARATIVES = {'after', 'outer'}
SUBJECTS = {'i', 'you', 'he', 'she', 'it', 'we', 'they', 'there'}
DETERMINERS = {'the', 'a', 'an', 'my', 'your', 'his', 'her', 'its',
              'our', 'their', 'this', 'that', 'these', 'those'}
CLAUSE_LINKS = {'that', 'and', 'so', 'but', 'because', 'then', 'if',
                'when', 'where', 'while', 'although'}
PREPOSITIONS = {'of', 'in', 'on', 'at', 'for', 'with', 'from', 'to',
                'by', 'into', 'among', 'between', 'against', 'over', 'under'}


@lru_cache(maxsize=8192)
def comparative(word):
    if word in {'more', 'less', 'better', 'worse', 'further', 'farther'}:
        return True
    if len(word) < 5 or not word.endswith('er') or word in NON_COMPARATIVES:
        return False
    # Reject apparent -er inflections that are really established nouns/verbs.
    if word not in {'lower', 'longer', 'closer'} and any(
            word in wordnet.base_forms(word, pos) for pos in ('noun', 'verb')):
        return False
    return any(base != word for base in wordnet.base_forms(word, 'adjective'))


def article_context(left):
    """Is this 'the [comparative]', and does 'the' open a clause?"""
    match = re.search(r'\b(the)\s+(?:(?:much|far|even|still)[ -]+)?$', left, re.I)
    if not match:
        return False, False, ''
    before = left[:match.start()]
    words = re.findall(r'[A-Za-z]+', before)
    previous = words[-1].lower() if words else ''
    initial = (match.group(1) == 'The' or not before.strip()
               or before.rstrip()[-1:] in ',;:.!?—'
               or previous in CLAUSE_LINKS)
    return True, initial, previous


def degree_value(word, initial, previous):
    if word == 'more':
        if initial:
            return 15.5
        return 3.0 if previous in PREPOSITIONS | {'all'} else 7.0
    if word in {'less', 'fewer'}:
        return 10.5 if initial or word == 'fewer' else 4.0
    if word in {'better', 'worse'}:
        return 10.0 if initial else 4.5
    if word == 'lower':
        return 2.2 if initial else 0.3
    if word == 'earlier':
        return 6.0 if initial else 0.5
    return 6.0 if initial else 2.6


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = (text + token)[-180:]
    value = 0.0
    if token == '越' or (token.startswith('越')
                        and token[1:] in set('多大高小长好是')):
        value = 2.5
    matches = list(re.finditer(r'[A-Za-z]+', text))
    if not matches or matches[-1].end() != len(text) or not token[-1:].isalpha():
        return (doc, text), value
    current = matches[-1]
    word = current.group().lower()
    left = text[:current.start()]
    definite, initial, previous = article_context(left)
    if comparative(word):
        value = degree_value(word, initial, previous) if definite else 0.08
        if re.search(r'\bmore\s+and\s+$', left, re.I) and word == 'more':
            value = 1.5
    if word in {'fuck', 'hell'} and definite:
        value = 5.0
    if len(matches) >= 2:
        prior = matches[-2]
        pw = prior.group().lower()
        prior_left = text[:prior.start()]
        gap = text[prior.end():current.start()]
        if gap.strip():
            return (doc, text), float(value)
        framed, onset, _ = article_context(prior_left)
        # 'the more detailed the ...' and 'the more eagerly we ...'
        extended = re.search(r'\bthe\s+(more|less)\s+$', prior_left, re.I)
        degree = comparative(pw)
        if extended and pw != 'like' and bool(
                {'adjective', 'adverb'} & wordnet.parts_of_speech(pw)):
            framed, degree = True, True
        else:
            extended = None
        if degree and (word in SUBJECTS or word in DETERMINERS):
            if not framed:
                value = 0.0 if pw in {'later', 'earlier'} else 2.0
            elif word in {'this', 'that', 'these', 'those', 'there'}:
                value = 1.0
            elif extended:
                value = 10.5
            elif pw == 'more':
                value = 7.2
            elif word == 'the':
                value = 12.5 if pw == 'better' else 8.5 if pw == 'less' else (
                    15.0 if onset else 12.0)
            else:
                value = (10.5 if onset else
                         3.0 if word in DETERMINERS else 6.0)
        elif degree and framed and word == 'of':
            value = 3.5
        elif (pw in {'more', 'less'} and framed
              and 'adjective' in wordnet.parts_of_speech(word)):
            value = 1.2
    return (doc, text), float(value)

programs.haiku:
"""Proportional comparatives: "the more X, the less Y", "the bigger the lottery, the ...".

The component reads the English proportional construction "the <comparative>, the
<comparative>". It fires:
- on a comparative word right after "the". Strongest for more / less / fewer that
  open a clause ("The more ...", "..., the more ...", "that the more ..."); weaker for
  other comparatives, and weaker still after a preposition ("of the larger ...", "in
  the lower ...", "to the higher ...");
- on the second "the" after a comparative: "the higher *the* degree", and two words on
  after "the more" ("the more frequent *the* collisions");
- on the subject pronoun just after "the more" ("the more *you* pull the fish", "the
  less *we* accept").
A comparative not introduced by "the" ("become more", "more than") gives nothing. A
Chinese 越 ("the more") gives a small value.

The rule looks back at most two tokens, within the same document, and keeps one small
state: how many tokens ago the last "the + comparative" was.
"""

READS = ()

MORE = {"more", "less", "fewer"}
COMPARATIVES = MORE | {
    "higher", "lower", "bigger", "larger", "smaller", "greater", "lesser", "better",
    "worse", "older", "younger", "farther", "further", "longer", "shorter", "wider",
    "narrower", "faster", "slower", "easier", "harder", "later", "earlier", "stronger",
    "weaker", "cheaper", "closer", "nearer", "deeper", "messier", "clearer", "colder",
    "hotter", "cooler", "warmer", "heavier", "lighter", "smarter", "wiser", "quicker",
}
PRONOUNS = {"you", "we", "i", "it", "they", "he", "she", "one", "your", "our"}
# tokens after which a new clause starts
CLAUSE_START = {"", ".", ",", ";", ":", "!", "?", "\n", "that", "and", "but",
                "<|endoftext|>"}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    # carry: how many tokens ago the last "the + comparative" was, if at most two
    # tokens back, else None
    last = carry
    t = prefix.position
    docs = prefix.document_ids
    # the current token and the two before it, blank if before the row or another document
    words = ["", "", _word(prefix.token_strings[t])]
    for back in (1, 2):
        if t - back >= 0 and docs[t - back] == docs[t]:
            words[2 - back] = _word(prefix.token_strings[t - back])
    pp, p, w = words
    dist = None if last is None else last + 1
    value = 0.0
    if "越" in w:
        value = 2.3
    elif w in COMPARATIVES and p == "the":
        if pp in CLAUSE_START:
            value = 15.0 if w in MORE else 5.0
        else:
            value = 5.0 if w in MORE else 1.8
        dist = 0
    elif dist == 1 and w == "the":
        value = 15.0 if pp == "the" else 1.0
    elif dist == 1 and w in PRONOUNS:
        value = 8.0
    elif dist == 2 and w == "the":
        value = 12.0
    elif dist == 2 and w in PRONOUNS:
        value = 6.0
    if dist is not None and dist > 2:
        dist = None
    return dist, value

programs.sol:
"""Approximate a Chinese counter-and-aspect response using surface grammar.

Unquantified 个/個 is strongly negative after a verb, less so in compounds
or Japanese text. A preceding number or determiner suppresses this response.
了 and other counters have smaller, context-dependent negative responses.
Repeated middle dots are a separate small positive mode. Weak lexical
variation elsewhere is not modeled.
"""
from functools import lru_cache
import regex
import cedict
import wordnet

READS = ()
QUANTIFIERS = frozenset(
    '这這那哪每各某整几幾两兩'
    '些数數多少半余餘单單'
)
COUNTERS = frozenset(
    '位件条條份只隻座片颗顆'
    '本张張枚根块塊种種名头頭'
)
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
HAN = regex.compile(r'\p{Script=Han}+')


@lru_cache(maxsize=8192)
def word_classes(word):
    glosses = cedict.glosses(word)
    verb = any(g.startswith(('to ', '(coll.) to ', '(literary) to '))
               for g in glosses)
    adjective = any('adjective' in wordnet.parts_of_speech(g) for g in glosses)
    return verb, adjective, bool(glosses)


def quantity(text):
    return bool(text) and (text[-1].isnumeric() or
                          text[-1] in QUANTIFIERS or text.endswith('若干'))


def predict(s, previous, last, japanese):
    s = s.replace('個', '个')
    if s == '个':
        if quantity(previous) or quantity(last):
            return 0.2
        if japanese:
            return -2.3
        if last == '了':
            return -7.5
        if last == '是':
            return -5.8
        if last == '的':
            return -2.3
        if last in ('有', '当', '當', '无', '無'):
            return -5.0
        if last in '我你他她它您咱' and last:
            return -5.5
        verb, _, known_word = word_classes(previous)
        if verb:
            return -7.7 if len(previous) == 1 else -5.2
        if not known_word and word_classes(last)[0]:
            return -5.4 if '\ufffd' in previous else -7.0
        return -3.4 if HAN.fullmatch(last) else -1.2
    if '个' in s and HAN.fullmatch(s):
        before, _, after = s.partition('个')
        if before == '了':
            return -7.5
        if before in ('了一', '有一'):
            return -0.7
        if before.endswith('一'):
            return -0.32
        if before and not quantity(before):
            return -2.7
        if not before:
            return -0.7 if after == '人' else -0.1
    if s == '了':
        verb, adjective, _ = word_classes(previous)
        if japanese:
            return -0.28
        if verb:
            return -0.88 if len(previous) == 1 else -0.26
        return -0.17 if adjective else -0.54
    if s in ('了一', '有一'):
        return -0.7
    if s == '不了':
        return -1.5
    if len(s) == 1 and s in COUNTERS:
        if quantity(previous) or quantity(last):
            return 0.04
        return -0.28 if word_classes(previous)[0] else -0.09
    if s == '得':
        return -0.25
    if len(s) >= 2 and not s.strip('·'):
        return 0.65 if previous.endswith('·') else 0.1
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', b''
    else:
        _, previous, tail = carry
    history = tail.decode('utf-8', 'replace')
    last = history.rstrip()[-1:]
    s = prefix.token_strings[-1]
    value = predict(s, previous, last, bool(KANA.search(history)))
    tail = (tail + prefix.token_bytes[-1])[-96:]
    return (doc, s.strip(), tail), value

"""Negative pulses on university/uni- spellings and name-introducing 'of'.

The response is spelling-sensitive: 'univ' abbreviations and split pieces of
'universit-' can be stronger than a whole 'University' token. Transliteration
lets the same rules cover the related Latin and Cyrillic university words.
Smaller rules cover higher education, United Nations, East Asian terms,
similar -versity endings, and split uni-/unver- beginnings.
Unmatched text receives zero. Only a short byte tail is kept between tokens.
"""
import re
from anyascii import anyascii

READS = ()
LETTERS = r'[^\W\d_]+'


def last_word(text):
    match = re.search('(' + LETTERS + r'\.?)[\s]*$', text)
    return match.group(1) if match else ''


def response(tail, token):
    text = tail.decode('utf-8', 'ignore')
    previous = last_word(text)
    before = anyascii(previous).lower()
    raw = token.decode('utf-8', 'ignore')
    spelling = anyascii(raw.strip())
    word = spelling.lower()
    capital = previous[:1].isupper()

    if word == 'of' and before in ('university', 'univ', 'univ.'):
        if re.search(r'(State|National)\s+University$', text):
            return -5.0
        if not capital:
            return -7.0 if before == 'university' else -9.5
        return -13.2 if before == 'university' else -16.0
    if word == 'de' and re.match(r'universi[td]', before):
        return -3.5
    if word == '.' and before == 'univ':
        return -4.0
    if word == 'education' and before == 'higher':
        return -4.1 if spelling[:1].isupper() else -2.7
    if word == 'nations' and before == 'united':
        return -2.8

    if word == 'university':
        if spelling[:1].isupper():
            return -4.5 if before == 'the' else -5.3
        return -2.9 if before == 'the' else -4.0
    if word == 'universities':
        return -2.8
    if word == 'univ':
        return -10.7
    if word in ('uni', 'unis'):
        return -1.8
    if word == 'univers':
        return -4.1
    if word.startswith('universitet'):
        return -4.7
    if re.match(r'universi(?:t|d)', word):
        return -9.5
    if word.startswith('univers'):
        return -0.3 if word.startswith('universal') else -0.8
    if '大学' in raw or '大學' in raw:
        return -1.8

    # A continuation has no leading space or punctuation.
    if raw and raw[0].isalpha() and text and text[-1].isalpha():
        if before.endswith('un'):
            if word == 'iv':
                return -17.0
            if word == 'iver':
                return -11.5
            if word == 'iversity':
                return -9.0
            if word in ('ivers', 'vers'):
                return -5.0
            if word.startswith('i') and not word.startswith('iq'):
                return -0.5
            if word.startswith('ver'):
                return -1.2
        if before.endswith('uni') and word.startswith(('ver', 'wers')):
            return -5.0
        if before.endswith('univer') and word == 's':
            return -4.7
        if before.endswith(('univers', 'unvers', 'univer')):
            if word.startswith('itet'):
                return -15.0
            if word.startswith('i'):
                return -12.0
        if before.endswith('univers'):
            return -1.0
        if re.search(r'universit[ae]?t?$', before):
            return -4.5
        if before.endswith(('vers', 'vars')) and word in ('ity', 'ite'):
            return -3.8
        if raw == '학' and text.endswith('대'):
            return -6.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry and carry[0] == doc else b''
    token = prefix.token_bytes[-1]
    value = response(tail, token)
    return (doc, (tail + token)[-128:]), value

"""A local noun-phrase reference detector, not a coreference resolver.

The strongest responses are negative: noun-introducing 'such', its article
in 'such a', and attributive 'said'. Noun-following 'such as/that' stays
weak. Prepositions, clause openings and dictionary grammar distinguish
these uses. Smaller responses cover descriptive modifiers, demonstratives
and quantifiers in several languages. A byte tail joins split words;
state resets at document boundaries. Other tokens receive zero.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
PREP = set('of in on at by for from to with into under over upon within '
           'through after before without during against'.split())
BE = set('is are was were be being been'.split())
OPENERS = set('if when whenever unless whether although because all any '
              'each every many first that which how while then so can '
              'could would should must may might do does did'.split())
VERB_CUES = set('to can may will must could would should not we they '
                'you he she it who'.split())
MODIFIERS = set('present proposed given remaining corresponding affected '
                'returned produced latter observed claimed'.split())
ROMANCE = set('di della delle gli che una uno de del que las los para '
              'por en le les des du une et dans pour'.split())
# Closed-class reference markers and quantifiers, grouped by language/use.
FORMS = (
    (-4.1, 'такой такая такие таких таким такого такому такую такое '
           'такими таком данный данного данной данная'),  # Russian such/given
    (-2.1, 'этот эта эти этих этого этому этой'),  # Russian this
    (-4.6, 'این هر'),  # Persian this/every
    (-3.0, 'همین همان چنین آن هیچ'),  # Persian deictics and no/none
    (-2.5, 'هذه هذا تلك ذلك أي بأي لأي'),  # Arabic this/that/any
    (-1.6, 'tout toute tous toutes todo toda todos todas cada'),
    (-1.2, 'esse essa esses essas diese dieser dieses'),
)
FORMS = tuple((v, set(words.split())) for v, words in FORMS)


@lru_cache(maxsize=2048)
def parts(word):
    return wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, prev, older, last = b'', '', '', 0.0
    else:
        _, tail, prev, older, last = carry
    raw = prefix.token_strings[-1]
    before = tail.decode('utf-8', errors='ignore')
    tail = (tail + prefix.token_bytes[-1])[-256:]
    m = re.search(r'[^\W\d_]+\Z', tail.decode('utf-8', errors='ignore'))
    whole = m.group().lower() if m else ''
    w, p, q = raw.strip().lower(), prev.strip().lower(), older.strip().lower()
    boundary = w == whole
    v = 0.0
    if whole == 'such':
        v = -0.7
        if p in PREP or p in OPENERS:
            v = -5.8
        elif p in BE or p == 'as':
            v = -1.8
        elif p in {'no', 'one', 'single', 'other', 'and', 'not'}:
            v = -3.3
        elif p in {'have', 'has', 'had', 'or', 'but'}:
            v = -4.7
        elif p == ',':
            v = -1.3
        else:
            match = re.search(r'([A-Za-z]+)\s*$', before)
            word = match.group(1).lower() if match else p
            pos = parts(word)
            if 'verb' in pos:
                v = -0.7 if 'noun' in pos else -5.3
                if word.endswith('ing') or q in VERB_CUES:
                    v = -5.3
                elif 'adjective' in pos:
                    v = -2.0
            elif 'adjective' in pos and 'noun' not in pos:
                v = -3.5
        if prev.strip() == 'In':
            v = -8.4
        if p in {'.', ';'} or q in {'however', 'therefore', 'indeed'}:
            v = -5.5
        if raw.strip() == 'Such' and p not in {'.', ';'}:
            v = -3.0
    elif w in {'a', 'an'} and boundary:
        if p == 'such':
            v = last - 0.35
        elif p in {'if', 'when', 'whenever', 'unless'}:
            v = -1.45
        elif p in {'for', 'that', 'which'}:
            v = -0.3
    elif w == 'said' and boundary:
        v = -11.5 if p == 'the' else (-8.5 if p in PREP else 0.18)
        if p in {',', 'and'}:
            v = -0.8
        if raw == ' Said' and p == '.':
            v = -7.8
    elif w in {'above', 'foregoing', 'aforementioned'} and boundary:
        v = -3.5 if p == 'the' or w != 'above' else 0.0
    elif w in {'resulting', 'obtained'} and boundary and p == 'the':
        v = -2.8
    elif w in MODIFIERS and boundary and p in {'the', 'a', 'an'}:
        v = -1.4
    elif w in {'this', 'that', 'these', 'those', 'our'} and boundary:
        v = -0.4 if p in PREP else -0.1
        if w == 'that' and p in {'in', 'of', 'at', 'if'}:
            v = -1.4
    elif w in {'bu', 'bir', 'her'} and boundary:
        if any(c in before[-200:] for c in 'ıİğĞşŞ'):
            v = -5.0 if w == 'bu' else -3.7  # Turkish this/a/every
    elif w in {'ce', 'ces', 'cet', 'cette'} and boundary:
        if not raw.strip().isupper():
            v = -3.5 if w == 'cet' else -2.3  # French demonstratives
    elif whole in {'tel', 'tels', 'telle', 'telles', 'tal', 'tale', 'tali', 'tales'}:
        nearby = set(re.findall(r'[^\W\d_]+', before.lower()))
        if len(nearby & ROMANCE) >= 2 or p in ROMANCE:
            v = -4.8  # French, Spanish and Italian equivalents of 'such'
    elif w in {'この', 'その', 'という', 'といった', 'と言う', 'これら', 'これらの'}:
        v = -1.3
    elif w == 'いう' and p.endswith('と'):
        v = -3.5
    elif w in {'上述', '该', '該'} or w in {'記', '述'} and p in {'上', '下'}:
        v = -3.0
    elif w in {'这些', '這些', '这一', '這一', '這個', '这个'}:
        v = -0.6 if w == '这个' else -1.6
    elif w == '本':
        v = -0.5 if before[-1:].isalnum() else -2.7
    elif (w in {'이', '그', '해당'} and boundary or
          whole in {'이런', '이러한', '그런', '그러한'}):
        v = -5.0 if w == '해당' else (-2.0 if w == '그' else -3.0)
    else:
        for amplitude, forms in FORMS:
            if whole in forms:
                v = amplitude
                break
    return (doc, tail, raw, prev, v), v

programs.haiku:
"""Determiners that point back to something already named ("in such a case",
"the said patent", "of this paper"). Negative activation on those words."""

READS = ()

# Typical strength (negative activation) of each referring word when it opens a noun phrase.
STRENGTH = {
    " such": 6.0, " Such": 5.0,
    " said": 5.0, " aforementioned": 2.5, " foregoing": 3.0, " latter": 1.2,
    " above": 2.8, " present": 1.2, " resulting": 2.6, " proposed": 1.6, " given": 1.0,
    " this": 0.3, " these": 0.5, " those": 0.3, " that": 0.6,
}
# Demonstratives and "such" in other languages (this/such/that: Turkish, French, Spanish,
# German, Russian, Korean, Japanese, Chinese); all fire like "such".
FOREIGN = {" bu", " bir", " ce", " cet", " cette", " ces", " tal", " tale", " este", " esta",
           " dich", " dicho", " таких", " такие", " таким", " этой", " этот", "该", "这种", "这些"}
# Words that open a noun phrase: a referring word after one of these is a determiner.
OPENERS = {" the", "The", " of", " in", " for", " to", " all", " at", " from", " by", " under",
           " with", " on", " into", " If", " if", " that", " In", " For", " no", " and", " or",
           " upon", " within", " through"}

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = toks[-2] if same_doc else ""
    cur = toks[-1]
    # The article right after "such" ("such a method") is the strongest case.
    if cur in (" a", " an") and prev in (" such", " Such"):
        return None, -5.0
    base = STRENGTH.get(cur, 6.0 if cur in FOREIGN else 0.0)
    if base == 0.0:
        return None, 0.0
    if prev in OPENERS:
        factor = 1.0
    elif prev == ",":
        factor = 0.3
    else:
        factor = 0.15
    return None, float(-base * factor)

programs.sol:
"""Approximate the response at the verbal part of a mathematical definition.

Examples are 'Let X be a ...' and 'where x is the ...'. Symbol-like
subjects raise the prediction on the verb and the following determiner;
'let' and 'where' strengthen particular constructions. Letter case, short
names, Greek letters, math delimiters, brackets and numbers are surface
proxies, not a mathematical parser. The amplitudes are rounded training
estimates. Most other tokens are assigned zero, omitting their weak and
idiosyncratic responses. A short text buffer resets between documents.
"""

import re
import unicodedata

READS = ()

BE = {'is','are','be','being'}
ARTICLES = {'a','an','the','any','some','two'}
NAMING = {'denote','denotes','represent','represents','stands','shows'}
CUES = re.compile(
    r'\b(let|where|if|suppose|denote|denotes|define|defined|consider|take)\b',
    re.I,
)
WORD = re.compile(r'([a-zA-Z]+)$')
LINKS = {
    'and','or','that','where','when','if','with','let','suppose','assume',
    'then','so','thus','since','because','while','although','unless','for',
}
RESPONDING_WORDS = BE | ARTICLES | NAMING

def subject_kind(text):
    # Inspect the end of a potential subject, not just a subword token.
    text=text.rstrip()
    if not text: return 'none'
    if text.endswith(('$',r'\)',r'\]')): return 'math'
    if text[-1] in ')]}': return 'bracket'
    if text[-1].isdigit(): return 'number'
    if text[-1]=='�': return 'symbol'
    if 'GREEK' in unicodedata.name(text[-1],''): return 'symbol'
    m=WORD.search(text)
    if m:
        w=m[1]
        if m.start() and (text[m.start()-1].isalpha()
                          or text[m.start()-1] in "'’"):
            return 'word'
        if len(w)==1:
            before=text[:m.start()].rstrip()
            prior=WORD.search(before)
            # 'column A' is weaker evidence than a bare variable A.
            if prior and len(prior[1])>1 and prior[1].lower() not in LINKS:
                return 'qualified'
            return 'symbol'
        if len(w)<=4 and w.isupper(): return 'acronym'
        if len(w)<=3 and '_' in text[-len(w)-2:]: return 'symbol'
    return 'word'

def describe(text, word):
    # On a determiner, look through the preceding definition verb.
    text=text.rstrip()
    cop=re.search(r'\b(is|are|be|being|denote|denotes|called|represents|represent)\s*$',text)
    previous=cop[1] if cop else ''
    if word in ARTICLES and cop:
        text=text[:cop.start()].rstrip()
    kind=subject_kind(text)
    matches=list(CUES.finditer(text[-100:]))
    cue=matches[-1][1].lower() if matches else ''
    if cue not in ('let','where','if'): cue='other' if cue else 'none'
    return kind,previous,cue

def definition(kind, cue):
    if kind in ('symbol','math'):
        return {'where':5.5,'if':2.7,'let':2.4,'other':3.0}.get(cue,1.9)
    if kind=='qualified': return 0.8
    if kind=='number': return 2.1 if cue=='where' else 0.4
    if kind=='acronym': return 1.0 if cue!='none' else 0.45
    if kind=='bracket':
        return {'where':2.5,'if':0.9,'let':1.1,'other':1.0}.get(cue,0.2)
    return 0.02

def predict(word, kind, prev, cue):
    if word in ('is','are','denotes','represents','represent','stands','being'):
        value=definition(kind,cue)
        if word=='are' and kind=='word': return -0.07
        if word=='being' and kind in ('symbol','math'): return 3.5
        return value
    if word=='be':
        if cue=='let':
            return {'symbol':9.0,'math':10.,'bracket':7.,'number':7.,
                    'acronym':6.5,'qualified':4.0}.get(kind,0.65)
        return definition(kind,cue)*0.25
    if word=='denote':
        return 1.1 if kind in ('word','qualified') else 5.0
    if word=='shows':
        return 0.8 if kind in ('number','symbol') else 0.05
    if word in ARTICLES:
        if prev in ('is','are','being'):
            if kind in ('math','symbol','none'):
                value={'where':6.5,'if':4.8,'let':4.9,'other':4.5}.get(cue,3.5)
            elif kind=='number': value=4.5 if cue=='where' else 1.1
            elif kind=='qualified': value=2.8
            elif kind=='acronym': value=3.5 if cue=='let' else 1.1
            elif kind=='bracket':
                value=5.3 if cue=='where' else (1.5 if word=='the' else 0.3)
            else:
                value=0.2 if word=='the' else 0.0
                if cue=='where': value=1.6 if word=='the' else 0.4
            return value
        if prev=='be':
            strength={'symbol':1.,'math':1.,'bracket':.9,'acronym':.7,
                      'number':.6,'word':.2,'none':.8}.get(kind,0.)
            if cue=='let': return strength*(5.2 if word=='the' else 9.0)
            return strength*1.0
        if prev in ('denote','denotes'): return 4.8 if word=='the' else 1.8
        if prev=='called': return 1.2
        if kind in ('math','symbol') and cue=='other': return 3.5
        if kind=='math' and cue=='let': return 5.0
    return 0.0

def step(carry, prefix, upstream):
    doc=prefix.document_ids[-1]
    if carry is None or carry[0]!=doc: text=''
    else: text=carry[1]
    token=prefix.token_strings[-1]
    word=token.strip().lower()
    value=0.0
    if word in RESPONDING_WORDS:
        kind,prev,cue=describe(text,word)
        value=predict(word,kind,prev,cue)
    return (doc,(text+token)[-250:]),float(value)

"""A spelling-based approximation to a short 'di' syllable detector.

The negative response is strongest for short vowel sequences, especially
across a token boundary. Long surrounding pieces weaken it. Transliteration
allows the same rules to cover Greek, Cyrillic and kana spellings. Case and
Latin accents adjust the strength; separate de/do/d receive small offsets.
Numerical strengths were fitted on training examples. This does not
distinguish words' meanings or infer the document's language.
"""
import codecs
import re
import unicodedata
from functools import lru_cache
import regex
from anyascii import anyascii

READS = ()
VOWELS = 'aeiouy'
BASE = {'initial': .911, 'within': .164, 'split_d': 2.782, 'split_di': 1.990}
VOWEL = {'a': 1.988, 'e': 2.059, 'i': .826, 'o': 1.744, 'u': 1.089, 'y': .760}
INITIAL = {'a': 1.566, 'e': .529, 'o': 1.207, 'y': .774}
WORD = {'d': -.30, 'D': -.04, 'de': -.40, 'De': -.23, 'DE': -.20,
        'do': -.12, 'Do': -.12, 'DO': -.18}

@lru_cache(maxsize=20000)
def spelling(text):
    # Han readings are not literal spellings of alphabetic syllables.
    if regex.search(r'\p{Script=Han}|\p{Script=Hangul}', text):
        return ''
    return anyascii(text).lower()


def predict(previous, text):
    a, p = spelling(text), spelling(previous)
    b = a.strip()
    if not b:
        return 0.0
    if text.startswith(' ') and text.strip() in WORD:
        return WORD[text.strip()]
    if a[0].isalpha() and p.endswith('d') and a.startswith(('i', 'ai')):
        kind, before = 'split_d', len(p.strip()) - 1
        dai = a.startswith('ai')
        tail = a[2:] if dai else a[1:]
    elif a[0].isalpha() and p.endswith(('di', 'dy')) and a[0] in VOWELS:
        kind, before, tail, dai = 'split_di', len(p.strip()) - 2, a, False
    else:
        matches = list(re.finditer(r'd(?:ai|i)', b))
        if not matches:
            return 0.0
        match = matches[-1]
        before, tail = match.start(), b[match.end():]
        kind, dai = ('within' if before else 'initial'), match.group() == 'dai'

    n = len(tail)
    vowel = bool(tail) and tail[0] in VOWELS
    strength = BASE[kind] * (1.052 if not tail else VOWEL.get(tail[0], .161))
    strength *= .867 ** min(before, 9) * .825 ** max(0, before - 2)
    if n == 2:
        strength *= .708
    elif n >= 3:
        strength *= .348 if n <= 4 else .105 ** (n - 4)
    if n >= 2 and vowel and tail[-1] in 'lmnr':
        strength *= 1.573  # Syllable closed by a sonorant.
    if n >= 2 and tail[-1] == 's':
        strength *= .876
    if tail and not vowel:
        strength *= .634 if n > 1 else 2.626 if tail in 'lmnr' else 1.0
    if text.strip().isupper():
        strength *= .571
    if text.strip()[:1].isupper():
        strength *= 1.582
    if dai:
        strength *= 1.526 * (.235 if kind in ('initial', 'within') else 1.0)
    if kind == 'initial' and vowel:
        strength *= INITIAL.get(tail[0], 1.0)
    if tail and kind in ('initial', 'within'):
        if regex.search(r'\p{Latin}', text) and regex.search(
                r'\p{M}', unicodedata.normalize('NFD', text)):
            strength *= .188
    # A short embedded stem is less diluted than a long embedded spelling.
    if kind == 'within':
        strength *= 5.0 if not tail else 4.0 if before <= 1 else 1.0
    if kind == 'initial' and n >= 2 and vowel:
        if tail[0] in 'eo' and tail[-1] in 'lmnr':
            strength *= 2.0
    return -min(strength, 12.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder, previous = codecs.getincrementaldecoder('utf-8')('ignore'), ''
    else:
        _, decoder, previous = carry
    text = decoder.decode(prefix.token_bytes[-1])
    return (doc, decoder, text or previous), predict(previous, text)

programs.haiku:
"""layers.1.mlp.down_proj:5218 -- a 'di' detector (negative).

What it does: this component goes strongly negative on the syllable "di" (d + i) when it
is spelled inside a word, and it fires most when the current token completes "di" plus a
following vowel, as in the pieces "dia", "dien", "dial", "die", "dio" of words such as
Sand|ia, Verd|ien|st, plasmod|ia, Stud|ien, bed|ient, D|ior. Cyrillic д/и, Greek δ/ι and
Ukrainian і count as d and i. Standalone words that start with d also fire mildly:
" de", " di", " die", " died", " d". Everything else predicts 0.

Values are the typical sizes in the harvest: about -3 for a vowel-completed "di" fragment,
about -1.6 when the token ends in "di", and -0.3 to -1 for the standalone words.
"""

READS = ()

D_LETTERS = set("dдδ")          # Latin d, Cyrillic de, Greek delta
I_LETTERS = set("iиιі")         # Latin i, Cyrillic i, Greek iota, Ukrainian i
VOWELS = set("aeiouyаеиоуяэюы")
STANDALONE = {" de": -0.4, " di": -1.0, " die": -0.9, " died": -0.8, " d": -0.3}
FRAGMENT_VOWEL = -3.0           # "di" + vowel completed by the current short token
FRAGMENT_END = -1.6             # token ends with "di"
MAX_FRAGMENT = 4                # longer pieces are usually whole words, which stay near 0


def _letters(s):
    s = s.strip().lower()
    return s if s and all(c.isalpha() for c in s) else None


def _trailing(s):
    """The letters at the end of a token, lowercased ('-d' -> 'd')."""
    j = len(s)
    while j > 0 and s[j - 1].isalpha():
        j -= 1
    return s[j:].lower()


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    cur = strs[-1]
    if cur.lower() in STANDALONE:
        return None, STANDALONE[cur.lower()]
    cur_l = _letters(cur)
    if cur_l is None or len(cur_l) > MAX_FRAGMENT:
        return None, 0.0
    # The word so far: the current token plus the letters before it in the same document.
    parts = [cur_l]
    if not cur.startswith(" "):
        for j in range(len(strs) - 2, -1, -1):
            if prefix.document_ids[j] != prefix.document_ids[-1]:
                break
            s = strs[j]
            t = _trailing(s)
            if not t:
                break
            parts.insert(0, t)
            if s.startswith(" ") or t != s.strip().lower():
                break
    word = "".join(parts)
    start = len(word) - len(cur_l)
    for i in range(max(start - 1, 0), len(word) - 1):
        if word[i] in D_LETTERS and word[i + 1] in I_LETTERS and i + 1 >= start:
            if i + 2 < len(word):
                if word[i + 2] in VOWELS:
                    return None, FRAGMENT_VOWEL
            else:
                return None, FRAGMENT_END
    return None, 0.0

"""Line breaks near the start of a document.

layers.1.mlp.down_proj:5219 is a weak feature that answers to line breaks. Its clearest
job: the first line break in a document pushes the activation strongly negative, about
-0.7 a few tokens in and fading to about -0.25 far into the document. A bare paragraph
break token ("\\n\\n") is much weaker at first (about -0.2), and later paragraph breaks sit
slightly positive. Second and later single line breaks are weaker still, and ordinary
tokens are near zero.

A document starts at each change of document id; positions and line-break counts restart
there, as the model resets its positions at each document boundary.
"""

READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids[t]
    if carry is None or carry[0] != doc:
        start, breaks = t, 0  # first token of a new document
    else:
        _, start, breaks = carry
    s = prefix.token_strings[t]
    value = 0.0
    if "\n" in s:
        d = t - start  # tokens into the document
        paragraph = s.strip("\r") in ("\n\n", "\n\n\n")  # a bare paragraph break
        if breaks == 0:
            if paragraph:
                value = -0.2
            elif d < 2:
                value = -0.1
            elif d < 12:
                value = -0.7
            elif d < 40:
                value = -0.5
            elif d < 100:
                value = -0.35
            else:
                value = -0.25
        elif paragraph:
            value = 0.05 if breaks >= 2 else 0.0
        else:
            value = -0.15 if breaks == 1 else -0.03
        breaks += 1
    return (doc, start, breaks), value

programs.sol:
"""A small, partial predictor of phrase-to-predicate transitions.

Auxiliaries rise after commas and closing brackets, especially when the
bracketed phrase was long. Away from punctuation, a longer stretch without
a pronoun gets a smaller rise. Past-tense endings and words following an
auxiliary receive smaller positive values. Document starts are negative.
These cues summarize the harvest's recurring resumption examples; they
are not a full grammatical parse.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
AUXILIARIES = set(
    "am is are was were be been being do does did have has had "
    "can could may might must shall should will would".split()
)
PRONOUNS = set(
    "i you he she it we they this that these those there who which".split()
)
PREPOSITIONS = set(
    "of in on at to from with by for as into about over under "
    "through between after before without during than".split()
)
ADVERBS = set(
    "not also still already just only now then never always often "
    "ever very really actually further even probably possibly generally".split()
)
CONJUNCTIONS = set(
    "and or but so yet if because although while when where "
    "since unless until though whereas".split()
)


@lru_cache(maxsize=8192)
def common_word(word):
    return (word.isascii() and word.isalpha()
            and zipf_frequency(word, "en") > 6)


def estimate(token, word, s):
    previous, previous_word = s["previous"], s["previous_word"]
    if s["position"] == 0:
        capital = bool(token.strip()) and token.strip()[0].isupper()
        return -0.5661 if capital else -0.3647

    if word in AUXILIARIES:
        if "," in previous:
            return 0.5487
        if any(c in previous for c in ")]}"):
            return 0.6547 if s["open"] > 6 else 0.2892
        if s["sentence_tokens"] <= 8:
            return 0.0144
        if s["comma"] <= 8:
            return 0.0322
        if s["pronoun"] <= 8:
            return 0.0586
        return 0.2023 if len(word) >= 3 else 0.0892

    past_ending = word.endswith("ed")
    if "," in previous:
        if not common_word(word):
            return 0.2481 if past_ending else 0.0284
        if word in CONJUNCTIONS:
            return -0.0109
        return 0.1888 if s["end"] > 16 else 0.0945

    if previous_word in AUXILIARIES:
        if s["close"] <= 2:
            return 0.3166
        if past_ending:
            return 0.1211
        return 0.1185 if word in ADVERBS else 0.0297
    if past_ending:
        return 0.0473
    if previous_word.isalpha():
        return -0.0022
    if any(arrow in token for arrow in ("=>", "⇒", "->")):
        return 0.1939
    return 0.0566 if word in PREPOSITIONS else 0.0068


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = dict(doc=doc, position=0, previous="", previous_word="",
                     comma=99, close=99, open=99, pronoun=99, end=99,
                     sentence_tokens=0)
    s = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = estimate(token, word, s)

    # All ages are token distances; even a decimal point counts as a dot.
    ending = any(c in token for c in ".!?。")
    events = dict(comma="," in token,
                  close=any(c in token for c in ")]}"),
                  open=any(c in token for c in "([{"),
                  pronoun=word in PRONOUNS, end=ending)
    for name, event in events.items():
        s[name] = 1 if event else min(99, s[name] + 1)
    s["sentence_tokens"] = 0 if ending else s["sentence_tokens"] + 1
    s["position"] += 1
    s["previous"], s["previous_word"] = token, word
    return s, value

"""Approximate a contextual 'at' detector.

Location/affiliation uses are positive, especially education and birth;
looking or aiming at a target is negative. Word fragments and stack traces
are treated separately. Smaller rules recognize attendance, age expressions,
Slavic/Vietnamese location prepositions, addresses, and French articles
following prepositions. Unmodeled background variation is left near zero.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

LOOKING = set('look glance peek'.split())
DIRECTED = set('aim target direct gaze stare yell shout scream shoot laugh smile'.split())
AFFILIATION = set('educate study student professor lecturer teacher teach researcher '
                  'fellow fellowship associate graduate university college academy '
                  'school degree employed employment scientist postdoctoral'.split())
MEASUREMENT = set('center centre point vertex vertices evaluate calculate estimate '
                  'value rate price number field'.split())

@lru_cache(maxsize=8192)
def forms(word):
    return set(wordnet.base_forms(word)) | {word}


def predict(token, tail, previous):
    word = token.strip()
    low = word.lower()
    if low == 'at':
        if token == 'at' and tail and (tail[-1].isalpha() or tail[-1] == '_'):
            return -0.70  # Letters inside another word, not a preposition.
        if token.startswith('\t') or (previous.isspace() and len(previous) > 1):
            return 1.06   # Indented stack-trace 'at'.
        words = re.findall(r'[A-Za-z]+', tail[-90:])
        last = words[-1].lower() if words else ''
        roots = forms(last)
        if len(words) > 1 and (last in {'up', 'down', 'back', 'around'}
                               or last.endswith('ly')):
            if forms(words[-2].lower()) & (LOOKING | DIRECTED):
                return -1.54
        if roots & LOOKING:
            return -0.92
        if roots & DIRECTED:
            return -1.54
        if 'arrive' in roots:
            return -0.15
        if roots & AFFILIATION or re.search(
            r'\b(professor|student|lecturer|fellow|degree|bachelor|master)'
            r'\b[^,.;!?]{0,50}$', tail.lower()
        ):
            return 5.05
        if roots & {'attempt', 'try', 'go', 'stab', 'shot', 'jab'}:
            return 0.70
        if roots & {'born', 'bear'}:
            return 5.25
        if roots & {'good', 'bad', 'adept', 'skilled', 'proficient', 'excellent'}:
            return 1.26
        if roots & {'start', 'begin', 'end', 'finish', 'stop'} or roots & MEASUREMENT:
            return 1.66
        if word == 'AT':
            return 0.27
        if word == 'At':
            return 3.26
        return 3.89 if tail.rstrip().endswith('.') else 2.94

    if low in {'attend', 'attends', 'attended', 'attending'}:
        return 2.85
    boundary = token[:1].isspace() or not tail or not tail[-1].isalpha()
    if low == 'на' and boundary:
        return 1.11
    if word == 'na' and token.startswith(' '):
        return 0.67
    if word == 'ở' and token.startswith(' '):
        return 2.20
    if low == 'www':
        return 1.26 if tail.endswith('://') else 0.30
    if word == '@':
        return 1.52 if token == '@' and re.search(r'[A-Za-z][\w.+%-]*$', tail) else 0.17
    if low in {'la', 'le', 'les'} and token.startswith(' '):
        if re.search(r'\b[Dd]ans\s*$', tail):
            return -4.15 if low == 'la' else -2.05
        if re.search(r'\b(sur|par|pour|de|entre|selon)\s*$', tail):
            return -0.50
    if low == 'age' and re.search(r'\bat (?:the|a(?: relatively)? young)\s*$', tail):
        return 2.43
    if low == 'of':
        if re.search(r'\bat the age\s*$', tail):
            return 2.43
        if re.search(r'\bgraduate\s*$', tail):
            return 4.59
    if low == 'aged':
        return 3.89 if tail.rstrip().endswith(',') else 0.66
    if low == 'from' and re.search(r'\bgraduated\s*$', tail):
        return 1.79
    if low == 'by' and re.search(r'\b(published|awarded)\s*$', tail):
        return 2.42
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = predict(token, tail, previous)
    return (doc, (tail + token)[-180:], token), value

"""Sparse compound-ending and document-opening rules.

Chinese noun endings for ideologies, social classes, specialists, agents,
personnel, kinship, titles and goods receive positive values. Dictionary
words distinguish an occupational -jia from 'home'. The possessive/linker
之, destination 至, and unity/lineage morpheme 统 receive negative values,
as does productive -ization. Other text is nearly zero. Separate rules
cover a few code openings and a leading run of carriage returns.

This captures only a subset of the component's lexical responses, not a
complete noun detector. State is recent Chinese text, reset per document.
