READS = ()
SIMPLIFY = OpenCC('t2s')

@lru_cache(None)
def simplify(text):
    return SIMPLIFY.convert(text)

@lru_cache(None)
def completed_word(prior, token):
    text = prior + token
    for n in range(min(8, len(text)), len(token), -1):
        glosses = cedict.glosses(text[-n:])
        if glosses:
            return glosses
    return ()

@lru_cache(None)
def person_word(glosses):
    for gloss in glosses:
        if gloss.startswith(('to ', 'surname', 'variant', 'CL:')):
            continue
        head = re.sub(r'\([^)]*\)', '', gloss).split(';')[0].split()
        if head:
            head = head[-1].strip(',.')
