        return 2.6
    if token in {'主义', '主义者'}:     # -ism, -ist
        return 2.1 if any(w in meaning for w in
                          ('capitalism', 'imperialism')) else 1.0
    if token == '家' and 'capitalist' in meaning:
        return 2.2
    if token == '学家':                 # scholar/scientist ending
        return 1.2
    if token in {'者', '家'}:
        if person_word(glosses):
            return 0.65
        return 0.27 if token == '者' else -0.001
    if token == '人员':
