            return_run and raw == '\r'), value

"""Signed responses inside English possessive phrases.

A short possessive context gates preferences for the following word: naming words
and parent terms are negative; superlatives, answers, software artifacts, affectionate
address, and parts/sides are positive. Other words have only a weak response.
This is a lexical approximation, not a general sentiment or ownership classifier.
An intervening modifier can preserve the context; document boundaries clear it.
Small extra rules cover 'idea of' complements and introspection names.
"""
from functools import lru_cache
import wordnet

READS = ()
POSSESSORS = {
    'thy': 0.8, 'thine': 0.8, 'yer': 0.5,
    'my': 1.35, 'your': 1.24, 'his': 1.0, 'her': 0.85,
    'its': 0.44, 'our': 0.98, 'their': 1.13, 'whose': 0.14,
    "'s": 0.68, '’s': 0.69,
    'user': 0.93, 'personal': 0.67, 'best': 0.34, 'driver': 0.68,
}
# Each row is a familiar lexical class and its signed contribution.
CLASSES = (
    (-2.79, 'names', 'name names username surname nickname'),
    (1.77, 'software artifacts', 'code solution snippet version'),
    (2.58, 'judgment', 'opinion guess'),
    (2.17, 'decision or attempt', 'choice answer attempt'),
    (1.32, 'associates', 'friend friends buddy buddies partner partners companion'),
    (2.50, 'young dependents', 'baby babies child kid'),
    (1.61, 'affection', 'dear beloved love loved sweetheart'),
    (2.63, 'parts and sides', 'part parts side'),
)
CLASSES = tuple((v, frozenset(words.split())) for v, _, words in CLASSES)
MODIFIERS = {
    'own', 'first', 'new', 'personal', 'professional', 'current', 'next', 'initial'
}


@lru_cache(maxsize=8192)
def lexical_value(raw):
    w = raw.strip().lower()
    pos = wordnet.parts_of_speech(w)
    value = 0.02 + 0.09 * ('noun' in pos) + 0.06 * ('verb' in pos)
    if not raw.startswith(' '):
        value += 0.04 * raw.isalpha() + 0.39 * raw[:1].isupper()
    value += 0.42 * raw.startswith('_')
    if w == 'best':
        value += 4.31
    elif w == 'most':
        value += 3.0
    elif w in {'top', 'worst'} or (
        w.endswith('est') and any(
            base != w for base in wordnet.base_forms(w, 'adjective')
        )
    ):
        value += 2.57
    if wordnet.is_a(w, 'parent'):
        value -= 1.40
    for weight, words in CLASSES:
        if w in words:
            value += weight
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    if start:
        carry = (doc, '', 0.0)
    _, prev, previous_gate = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    gate = POSSESSORS.get(prev, 0.0)
    if prev in MODIFIERS and previous_gate:
        gate = previous_gate
    value = gate * lexical_value(raw) if gate else 0.0
    if raw == ' of':
        if prev == 'idea':
            value = 1.0 + 1.5 * previous_gate
        elif prev in {
            'way', 'side', 'understanding', 'dream', 'dreams', 'interpretation'
        }:
            value = 1.0 * previous_gate
    # Introspection names are the programming analogue of personal names.
    if word == 'name' and (prev.endswith('__') or prev.endswith('.')):
        value = -1.3 if prev == '__' else -2.5
    return (doc, word, gate), float(value)

