"""Layer 1, MLP down-projection, hidden unit 5223.

What it does, in plain terms: it reads "a possessive was just written, and the
possessed noun is coming". It is switched on by the word right after a possessive
determiner (my, your, his, her, its, our, their) or the possessive ending 's, and
its value depends on what that next word is:

  * superlatives such as "best", "most", "finest" ("my best", "their most") push
    it strongly positive;
  * words for a choice, contribution or answer ("your part", "my attempt",
    "their version", "your answer", "my opinion", "your code") push it positive;
  * words for names, kin and people ("my name", "his father", "your family",
    "my mom") push it negative;
  * other words after a possessive stay near zero.

Two rarer cases: the first token of each document sits slightly below zero, and a
run of repeated middle-dot tokens (leader dots) sits at a fixed negative value.
Everywhere else it is zero. Only the word lists and values below are used.
"""

READS = ()

POSSESSIVE = {"my", "your", "his", "her", "its", "our", "their", "'s", "’s"}
SUPERLATIVE = {"best", "most", "largest", "biggest", "greatest", "finest", "worst",
               "favorite", "top", "newest", "highest", "youngest"}
CHOICE_OR_CONTRIBUTION = {
    "part", "parts", "choice", "choices", "attempt", "attempts", "answer", "opinion",
    "solution", "version", "code", "side", "guess", "approach", "response", "responses",
    "request", "idea", "partner", "view", "views", "gift", "love", "dream", "dreams",
    "option", "preference", "advice", "offer", "promise", "wish", "wishes", "order",
    "command", "picks", "changes", "friend", "friends", "child", "kid", "kids", "baby",
    "dear",
}
KIN_OR_NAME = {"name", "names", "mother", "father", "mom", "dad", "parents", "family",
               "fathers", "cousin", "fellow", "wife", "husband", "face", "respective"}
DOT_RUN = "··"
STARTED = -0.3
DOT_VALUE = -1.2


def step(carry, prefix, upstream):
    t = prefix.position
    cur = prefix.token_strings[t].strip().lower()
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return carry, STARTED
    prev = prefix.token_strings[t - 1]
    if prev == DOT_RUN:
        return carry, DOT_VALUE
    if prev.strip().lower() not in POSSESSIVE:
        return carry, 0.0
    if cur in SUPERLATIVE:
        return carry, 3.0
    if cur in CHOICE_OR_CONTRIBUTION:
        return carry, 2.0
    if cur in KIN_OR_NAME:
        return carry, -1.0
    return carry, 0.0

