"""A lexical approximation to a boolean-test / predicate feature.

Comparisons, existence/emptiness checks, validity names and size queries
receive positive values. Nearby syntax distinguishes code and predicates
from ordinary prose. This recognizes spellings, not whether a test is true.
Only the last 120 characters are kept, separately for each document.
"""
import re

READS = ()


def activation(token, h):
    s = token.strip()
    name = s.lstrip('._-')
    w = name.lower()
    member = s.startswith(('.', '_')) or (
        token == token.lstrip() and h.endswith(('.', '_')))
    joined = member or (token == token.lstrip() and bool(
        re.search(r'[a-zA-Z_]$', h)))

    # Operators, including shell's numeric tests (-eq, -ne, ...).
    if s in {'eq', 'ne', 'lt', 'le', 'gt', 'ge'} and h.endswith('-'):
        return 4.6
    if s in {'!=', '!=='}:
        return 2.3
    if s == '≠':
        return 1.0
    if s in {'==', '==='}:
        return 0.5
    if s in {'<=', '>=', '≤', '≥'}:
        return 0.17
    if s in {'<', '>'}:
        return 0.3 if re.search(r'\b(if|for|while)\b', h[-70:]) else 0.0
    if s == ':=':
        return 0.59
    if s == '=':
        return 0.15 if token.startswith(' ') else 0.0
    if s in {'!', '(!', '!(', '(!('}:
        return 0.72 if '(' in s or token.startswith(' ') else 0.0
    if s == '0' and re.search(r'(?:[=!]=+|<|>)\s*$', h):
        return 0.4

    # Familiar boolean-query and assertion naming conventions.
    if re.match(r'(?:is|has|can|Is|Has|Can)[A-Z_]', name):
        return 2.2
    if re.match(r'(?:assert|Assert|toBe|toHave)[A-Z_]', name):
        return 0.95
    if joined and re.search(
        r'(?:Equal|Equals|Exist|Exists|Found|Present|Empty|Blank|Null)$', name):
        return 2.0
    if member:
        if w in {'length', 'len', 'size', 'count'}:
            if s.startswith('.'):
                return {'length': 1.95, 'len': 1.2,
                        'size': 1.4, 'count': 0.45}[w]
            return {'length': 1.1, 'len': 0.2,
                    'size': 0.15, 'count': 0.05}[w]
        if w in {'equal', 'equals', 'eq', 'ne', 'neq', 'identical'}:
            return 1.85
        if w in {'exist', 'exists'}:
            return 2.9
        if w in {'has', 'have'}:
            return 1.7
        if w in {'contains', 'includes', 'include'}:
            return 3.1 if w == 'contains' else 1.3
        if w in {'is', 'are'}:
            return 1.5
        if w in {'not', 'no', 'all', 'any', 'some'}:
            return 0.6

    # Named values and predicates, with a few local grammatical distinctions.
    if w in {'null', 'none', 'nil', 'nan'}:
        return 0.8 if re.search(r'(?:[=!]=+|\bis|\bnot)\s*$', h) else 0.23
    if w in {'true', 'false'}:
        return -0.1
    if w in {'empty', 'blank'}:
        return 2.0 if re.search(r'(?:[(!]|\bnot|\bis)\s*$', h) else 0.52
    if w == 'valid':
        return 1.3 if joined else 0.65
    if w in {'invalid', 'missing'}:
        return 0.6 if w == 'invalid' else 0.5
    if w in {'defined', 'undefined'}:
        if w == 'undefined':
            return 1.2
        return 1.65 if re.search(r'\bnot\s*$', h, re.I) else 0.17
    if w in {'ok', 'success'}:
        return 1.3 if re.search(r'(?:\.\.\.|test result:)\s*$', h) else 0.4
    if w in {'exist', 'exists', 'contains', 'matches'}:
        check = re.search(
            r'[{};`]|\\[nt]|\b(if|check|verify|ensure|file|directory|type)\b',
            h[-80:], re.I)
        return 1.25 if check else 0.12
    if w == 'found':
        if member:
            return 1.85
        return 1.9 if re.search(r'\b(not|no)(?:\s+\w+){0,2}\s*$', h, re.I) else 0.2
    if w == 'present':
        predicate = re.search(r'\b(is|are|be|not|no)(?:\s+\w+){0,2}\s*$', h, re.I)
        return 1.1 if predicate else -0.15
    if w in {'equal', 'same', 'less', 'greater', 'larger', 'smaller'}:
        if re.search(r'\bnot\s*$', h, re.I):
            return 1.3 if w == 'equal' else 0.35
        return 0.35 if re.search(r'\b(is|are|be)(?:\s+the)?\s*$', h) else 0.0
    if w == 'be':
        if re.search(r'\b(not|cannot|can.t)\s*$', h, re.I):
            return 0.5
        if re.search(r'\b(should|must|shall)\s*$', h, re.I):
            return 0.25
    if w in {'is', 'has'} and re.search(
        r'(?:!|\bbool|\bboolean|\bconst|\blet|\bvar)\s*$', h):
        return 2.0
    if w == 'not' and re.search(r'\b(if|and|or|assert)\s*$', h):
        return 0.2
    if w == 'in' and re.search(
        r'\b(?:for|foreach)\s*\(?\s*(?:(?:int|var|const|let)\s+)?'
        r'\w+(?:,\s*\w+)*\s*$', h):
        return 0.65
    if w in {'typeof', 'isinstance', 'issubclass', 'instanceof'}:
        return 1.05
    if w in {'len', 'grep'}:
        return 0.3 if w == 'len' else 0.8
    if len(s) == 1 and s.isascii() and s.isalpha() and h.endswith(' -'):
        return 0.6 if s in 'efdrwxsnzLh' else 0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    h = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(token, h)
    return (doc, (h + token)[-120:]), value

"""Local uses of question and exclamation marks.

Sentence-final questions are mildly negative; confirmation questions, unknown
values in formulas, and marks followed by closing punctuation are positive.
Code has several distinct uses: Java wildcard upper bounds, PHP/XML openers,
and Rust assertions/debug formatting. A colon after a YAML merge key and
an escaped equals sign have negative responses. Other tokens predict zero.
"""
import re
import unicodedata

READS = ()
QUESTIONS = '?？'
BANGS = '!！'
MARKS = QUESTIONS + BANGS
QUOTES = '\"\'’”」』'
ASSERTION = re.compile(r'(?:debug_)?assert(?:_(?:eq|ne))?$')


def step(carry, prefix, upstream):
