        value = -0.35 if previous.startswith(' ') else -0.25
        if not previous.strip().isalpha():
            value = -0.05
        if '\n' in token:
            value = -0.22 if '\n\n' not in token else 0.0
        if '？' in token:
            value += 0.25 if '\n' not in token else 0.45
        if token.startswith(' '):
            value += 0.18 if '\n\n' not in token else 0.65
        if ')' in suffix or '）' in suffix:
            value = 2.5 if ',' in suffix else 2.0
        elif any(c in '」』' for c in suffix):
