        elif ')' in token:
            value = 1.1
        elif any(c in QUOTES for c in token):
            value = 0.3
        if previous.endswith(tuple(MARKS)) and token[0] in BANGS:
            value = 3.7
            if previous[-1] in QUESTIONS:
