                 3.4 if position == 2 else 1.4)
    elif previous.endswith(tuple(MARKS)) and token and not token[0].isspace():
        if token.startswith((')', '）')) and '(' in previous:
            value = 3.4
        elif token.startswith((']', '」', '”', '"', "'")):
            value = 1.3
        elif token == '\ufe0f':
            value = 6.0  # Emoji-style variation selector attached to a mark.
        elif token == 'is' and previous.endswith('!'):
            value = 0.6
    return (doc, token, position + 1, (tail + token)[-48:]), value

"""A usually positive document-start pulse, plus negative code-layout cues.

Opening-token strength is estimated from its script and word/number/symbol
shape. Later, split indentation, declaration keywords, and block-opening
punctuation receive negative values. Ordinary prose is near zero. These are
coarse classes, not a lookup of the model's token-specific opening responses.
"""
import re
import unicodedata

READS = ()

def opening(s):
    word = s.strip()
    if s in {'package', 'import', 'from'}:
        return -2.3
    if s in {'const', 'var', 'def', 'function'}:
        return 0.1
    if s == '<|im_start|>':
        return 5.37
    if s.startswith('<|'):
        return 0.0
    if not word:
        if '\n' in s or '\r' in s:
            return -0.4
        if '\t' in s:
            return 0.3
        return 1.6 if len(s) == 1 else 2.4
    if word.isdigit():
        return -0.5
    letters = ''.join(c for c in word if c.isalpha())
    if not letters:
        if word == '\ufffd':
            return 1.9
        if word in ',，':
            return 2.4
        if word in '.。!?！？':
            return 0.0
        if word in "'’‘":
            return -1.2
        if len(word) == 1:
            category = unicodedata.category(word)
            return {'Ps': 1.2, 'Pe': 0.6, 'Sc': -0.3}.get(category, 0.6)
        return 0.6
    names = [unicodedata.name(c, '') for c in letters]
    if all('LATIN' in name for name in names):
        value = 4.5 + 0.08 * (min(len(letters), 10) - 4)
        value += 1.2 * s.startswith(' ')
        value -= 0.55 * letters.islower() + 0.6 * letters.isupper()
        value += 0.6 * (len(letters) != len(word))
        return value
    base = 1.6
    if any('CYRILLIC' in name for name in names):
        base = 2.8
    elif any('ARABIC' in name for name in names):
        base = 1.9
    return base + 0.5 * (min(len(letters), 4) - 1)


DECLARATIONS = frozenset(
    'const let var def fn func function class struct enum interface impl'.split()
)
TYPES = frozenset('int void String double float bool boolean char long short'.split())
BLOCK_LINE = re.compile(
    r'^\s*(?:(?:async|public|private|protected|static)\s+)*'
    r'(?:if|elif|else|for|while|try|except|finally|with|match|case|default|def|class)\b'
)


def ordinary(s, previous, line):
    if s == ' ':
        if previous and previous.strip(' \t') == '':
            return -0.5 if previous == ' ' else -1.8
        if previous.endswith('\n'):
            return -0.2
        if previous in ('\\n', 'n') and not line.strip():
            return -0.4
    # Token includes a source-code block opener and its line ending.
    if s.rstrip('\\').strip() in ('{', '){') and ('\n' in s or s.endswith('\\')):
        return 0.0 if previous.endswith('|') else -0.95
    # A colon ending a Python/control-flow line (rather than a prose colon).
    if ':' in s and all(c in " \t\r\n:)'\"\\]" for c in s):
        line_end = '\n' in s or s.endswith('\\')
        if BLOCK_LINE.match(line) or (line_end and ("'" in s or '"' in s)):
            return -1.6 if line_end else -1.2
    w = s.strip()
    # A declaration must start a line or follow indentation/a modifier,
    # not merely occur as a word in prose or inside another word.
    modifier = previous.strip() in {
        'pub', 'public', 'private', 'protected', 'static', 'export', 'const'
    }
    declaration_position = not line.strip() or previous.isspace() or modifier
    if declaration_position:
        if w in DECLARATIONS:
            if previous.isspace() and w in {'const', 'let', 'var'}:
                return -1.3
            if modifier and w in {'struct', 'class'}:
                return -1.6
            return -0.65
        if w in TYPES:
            return -0.4
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line = '', ''
        value = opening(s)
    else:
        _, previous, line = carry
        value = ordinary(s, previous, line)
    # Track a logical source line, including escaped newlines in quoted code.
    line = (line + s).replace('\\n', '\n').replace('\\r', '')
    line = line.rsplit('\n', 1)[-1][-300:]
    return (doc, s, line), value

