CODE_KEYWORDS = {'import', 'package', 'from', 'function', 'var', 'def', 'const', 'include', 'class', 'let', 'using'}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    body = tok.strip()
