    'identity': set('name identifier id type category description definition '
                    'title detail code label'.split()),
    'measure': set('size rate count number amount level quantity quality volume '
                   'length width height weight loss gain cost price fee temperature '
                   'time age duration period speed distance'.split()),
    'activity': set('management control processing process production generation '
                    'development acquisition creation sharing handling measurement '
                    'operation interaction distribution'.split()),
    'organization': set('system network center company industry agency authority '
                        'school service shop platform program department'.split()),
    'role': set('owner author manager manufacturer maker producer administrator '
                'worker employee member listener generator monitor'.split()),
    'relation': set('based related specific dependent driven oriented'.split()),
}
STOP = set(('a an the this that these those some any each every all both other '
            'another such no not as than of in on at by for from to with without '
            'into over under about through and or but if when while because '
            'although is are was were be been being am do does did have has had '
            'it its i me my we our us you your he his him she her they their them '
            'who which what there here so also more most less very just can could '
            'may might will would shall should must').split())

