def tags(word):
    w = word.lower()
    if w in STOP or (len(w) < 2 and w.isascii()):
        return frozenset()
    if not w.isascii():
        result = set()
        if not re.search(r'\p{Script=Han}', w):
            return frozenset()
        for gloss in cedict.glosses(w):
            g = re.sub(r'\([^)]*\)', '', gloss).strip()
            if g.startswith('to ') or len(g.split()) > 5:
                continue
            if re.search(r'particle|classifier|pronoun|preposition|variant of', g):
                continue
            words = re.findall('[a-zA-Z]+', g)
            if words:
                result.update(tags(words[0]))
                result.update(tags(words[-1]))
