RULES = (
    ('noun', 'noun', 0.0384),
    ('identity', 'word', 0.2665),
    ('organization', 'noun', 0.2625),
    ('activity', 'noun', 0.3164),
    ('measure', 'noun_only', 0.2514),
    ('relation', 'noun', 0.4404),
    ('role', 'word', 0.2158),
