        if '小' in s:
            return -1.0  # size: literally 'big-small'
        if s.startswith(('大部分', '大多数', '大多數', '大量', '大力')):
            return -0.4
        if s.startswith(('伟大', '偉大', '强大', '強大', '巨大', '庞大', '龐大')):
            return -2.0
        if s.startswith('的'):
