              'leur leurs fon'.split()),
    'es': set('mi mis tu tus su sus nuestro nuestra nuestros nuestras '
              'vuestro vuestra vuestros vuestras'.split()),
    'pt': set('meu minha meus minhas teu tua teus tuas seu sua seus suas '
              'nosso nossa nossos nossas vosso vossa vossos vossas'.split()),
    'it': set('mio mia miei mie tuo tua tuoi tue suo sua suoi sue '
              'nostro nostra nostri nostre vostro vostra vostri vostre'.split()),
}
