    'my':    (14.3, 14.8, 18.8, 14.4),
    'your':  (11.4, 11.4, 18.5, 14.1),
    'his':   (9.0, 10.0, 19.2, 16.5),
    'her':   (7.5, 8.1, 16.0, 10.8),
    'its':   (3.7, 8.8, 12.0, 11.7),
    'our':   (9.7, 14.0, 20.3, 15.5),
    'their': (9.0, 10.3, 18.0, 14.4),
}
