DECLARATIONS = set('import def int string const var new final'.split())


@lru_cache(maxsize=16384)
def word_scores(word):
    return tuple(max(0.0, zipf_frequency(word, lang) - 3.0)
                 for lang in LANGUAGES)


def recent_language(history):
    words = re.findall(r'[^\W\d_]+', history.lower())[-24:]
    scores = [0.0] * len(LANGUAGES)
