"""layers.1.mlp.down_proj:5234: a sparse feature with a few strong, readable triggers.

Most positions sit near zero, and the large values come from a handful of recognisable
contexts. Each rule reads only the last few tokens. The numbers are typical activations.

* Forum listings: the word " views" right after a view count. A count that starts a line
  ("...", newline, "47 views", or "2k views") gives about +13; after a blank line about +7;
  after a space mid-line about +3; otherwise about +1.
* File headers: " by" after " Created" ("Created by") gives about +1.
* Forum sidebar: " Questions" after " Similar" ("Similar Questions") gives about +3.5.
* Code namespaces: the segment after "using System." or "import android." when it is a
  known library: ".Text" (about +5), ".Collections" (about +3), android ".view" (about +2),
  ".support" and ".Windows" (about +1.2).
* HTML: the value of type="...": "text" about +6, "radio" about +2.6.
* "#include" (about +1.5).
* "Apache License" (about +1.7 on " License" after " Apache").
* LaTeX: a "{" after a font or environment command (\\begin, \\text, \\mathrm, \\bf, ...) is
  mildly negative (about -0.5). "center" right after "\\begin{" is strongly negative (about -4.5).
* Forum footer "Last edited": " edited" after "Last" is about -3.3.
* Bold markdown "**" starting a paragraph is mildly negative (about -0.9).

Everything else predicts 0.
"""

READS = ()

DIGITS = frozenset("0123456789")
LATEX_OPENERS = frozenset(["begin", "text", "textit", "textbf", "mathrm", "mathbf", "bf", "cal", "bb"])
SYSTEM_LIBS = {".Text": 5.0, ".Collections": 3.0, ".Windows": 1.2}
ANDROID_LIBS = {".view": 2.0, ".support": 1.2}
INPUT_TYPES = {"text": 6.0, "radio": 2.6}


def _views_value(toks):
    """Activation for a " views" token, from the count written just before it."""
    i = len(toks) - 2
    if i >= 0 and toks[i] == "k":  # "2k views"
        i -= 1
    start = i
    while start >= 0 and toks[start] in DIGITS:
        start -= 1
    if start == i:
        return 0.0  # no count before " views"
    if start < 0:
        return 13.0  # the count opens the row
    before = toks[start]
    if before == "\n\n":
        return 7.0  # the count starts a line after a blank line
    if before.endswith("\n"):
        return 13.0  # the count starts a line
    if before == " ":
        return 3.0  # the count is mid-line
    return 1.0


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
    if cur == " views":
        value = _views_value(toks)
    elif cur == " Questions" and prev == " Similar":
        value = 3.5
    elif cur == " by" and prev == " Created":
        value = 1.1
    elif prev == " System" and cur in SYSTEM_LIBS:
        value = SYSTEM_LIBS[cur]
    elif prev == " android" and cur in ANDROID_LIBS:
        value = ANDROID_LIBS[cur]
    elif prev == '="' and prev2 == "type" and cur in INPUT_TYPES:
        value = INPUT_TYPES[cur]
    elif cur in (" License", "License") and prev == " Apache":
        value = 1.7
    elif cur == "#include":
        value = 1.5
    elif cur == "{" and prev in LATEX_OPENERS:
        value = -0.5
    elif cur == "center" and (prev.endswith("\\") or prev == "{"):
        value = -4.5
    elif cur == " edited" and prev == "Last":
        value = -3.3
    elif cur == "**" and prev.endswith("\n\n"):
        value = -0.9
    else:
        value = 0.0
    return carry, value

