_NUMBERED_LINE = re.compile(r'\s*\d+\t\s*')


def _response(token, previous, tail, start):
    mark = token.strip()
    spacing = token.isspace() and '\n' not in token and '\r' not in token
    hashes = bool(mark) and set(mark) == {'#'}
    if len(mark) >= 4 and set(mark) == {'/'}:
        return -1.1
