    if (mark.startswith(('#', '//')) and len(mark) >= 4
            and divider and set(divider) <= {'=', '-'}):
        return -2.3
    if not (mark in ('//', '/*', '///', '--', '%', '-', '•', '·', '··',
                     '*', '**', '.', ')') or hashes
            or mark.startswith('/**')
            or (spacing and ('\t' in token or '\xa0' in token))):
        return 0.0

    line = tail.replace('\\n', '\n').split('\n')[-1]
    line_start = not line.strip() or bool(_NUMBERED_LINE.fullmatch(line))
    code = bool(_CODE.search(tail))
    escaped = '\\n' in tail[-100:]
    indented = bool(previous) and previous.isspace() and '\n' not in previous
    leading = token.startswith((' ', '\t'))
    newline = '\n' in previous

    if mark == '#':
        if start:
            return 0.44
        if not line_start:
            if '`' in previous:
                return -4.65
            return -0.5 if leading else 0.0
        if not code:
            return -1.0 if newline else -2.7
        if escaped and not leading:
            return -5.7
        return -4.2 if indented and len(previous) >= 8 else -3.3
    if mark == '//':
        if start:
            return 0.0
        if indented:
            if not line_start:
                return -2.6
            return -4.5 - float(escaped) if code else -2.8
        if leading:
            return -1.6
        if not code:
            return -1.8
        return -3.0 if newline else -4.8
    if mark in ('--', '%'):
        if not line_start or start:
            return 0.0
        return -1.0 if mark == '%' and leading else -3.6
    if mark == '/*':
        return -2.0 if indented else -1.2 if newline else -0.4
    if mark == '///' or mark.startswith('/**'):
        return -0.6 if token.endswith('\n') else -1.3
    if hashes:
        if start:
            return 0.42
        return -2.0 if escaped else -0.9 if code else -0.5
    if spacing:
        if len(token) == 1:
            return 0.0
        if newline:
            return -0.1
        return -0.55 if '\t' in token and len(token) >= 4 else -0.3
    if mark == '··':
        return -0.67
    if mark in ('-', '•', '·', '*', '**'):
        return -0.3 if line_start and not token.endswith('\n') else 0.0
    if mark in ('.', ')') and re.fullmatch(r'[0-9A-Za-z]{1,2}', line):
