    'ั': (1.35, 2.1),
    'ิ': (0.85, 6.1),
    'ี': (-0.05, 0.6),
    'ึ': (0.3, 0.3),
    'ื': (0.65, 2.6),
    'ือ': (0.18, 2.7),
    'ื่': (1.15, 2.35),
    'ี่': (-0.14, 4.1),
    '็': (0.7, 3.3),
}
TONE_MARKS = set('่้๊๋')
VOWELS = set('aeiouyɑɐɒæɛɜɞɪɔɵœøəʊʌɯ')


def predict(raw, text, history):
    b = raw
    if raw == b'\t' and not history:
        return 1.88
    if text == '\xa0':
        return 0.12
    # Unfinished UTF-8 prefixes: punctuation, Latin-1, and Gurmukhi.
    if b == b'\xe2\x80':
        return -0.75
    if b == b'\xc2':
        return 0.2
    if b == b' \xe2\x80':
        return -0.25
    if b in (b'\xe0\xa8', b'\xe0\xa9'):
        marked = history and ud.category(history[-1]).startswith('M')
        return (2.4 if marked else 0.28) if b[-1] == 168 else 0.0

    t = text.strip()
    if not t:
        return 0.0
    previous = history[-1:]
    preposed_e = bool(re.search('เ[ก-ฮ]{1,2}$', history))
    if t in THAI_VOWELS:
        return THAI_VOWELS[t][preposed_e]
    if all(c in TONE_MARKS for c in t):
        if previous == 'ั':
            return 4.1 if t == '่' else 3.6
        if previous == 'ิ':
            compound = bool(re.search('เ[ก-ฮ]{1,2}ิ$', history))
            return 8.4 if compound or t == '๊' else 5.5
        if previous == 'ุ':
            return 2.2 if t == '่' else 3.7
        if previous == 'ึ':
            return 0.85 if t == '่' else 3.0
        if t in ('๊', '๋'):
            if previous in ('ิ', 'ี'):
                return 6.0
            return 3.5 if t == '๊' else 1.2
        return 1.0 if previous == 'ื' else 0.1
    if (t in ('ย', 'ยว')
            and re.search('เ[ก-ฮ]{1,2}[ีิ][่้๊๋]?$', history)):
        return 4.0 if t == 'ย' else 1.5
    if t == '์':
        return 6.4 if re.search('เ[ก-ฮ]{1,2}ิ[ก-ฮ]$', history) else 0.0
    if len(t) > 1 and set(t) == {'·'}:
        return -0.35
    if len(t) != 1:
        return 0.0

    name = ud.name(t, '')
    if 'SMALL' in name and ('HIRAGANA' in name or 'KATAKANA' in name):
        kana_before = any(k in ud.name(previous or ' ', '')
                          for k in ('HIRAGANA', 'KATAKANA'))
        if 'SMALL TU' in name:
            return (2.5 if 'KATAKANA' in name else 1.9) if kana_before else 0.7
        if 'HIRAGANA' in name and kana_before:
            return 2.0 if 'SMALL YA' in name else 0.85
        return 0.0

    if 'CANDRABINDU' in name:
        return 4.8
    if 'ANUSVARA' in name:
        previous_name = ud.name(previous or ' ', '')
        vowel = previous_name.rsplit(' ', 1)[-1]
        if ud.category(previous or ' ').startswith('M') or vowel in (
                'A', 'AA', 'I', 'II', 'U', 'UU', 'E', 'AI', 'O', 'AU'):
            if vowel in ('AA', 'I', 'II', 'UU'):
                return 4.8
            return 2.6
        return 0.1
    if 'VIRAMA' in name:
        return 0.55
    if name == 'ARABIC SUKUN':
        return 2.0
    if name == 'ARABIC SMALL HIGH DOTLESS HEAD OF KHAH':
        return 5.0
    if name == 'ARABIC LETTER SUPERSCRIPT ALEF':
        return 3.4
    if name.startswith('COMBINING'):
        return 2.0 if previous.lower() in VOWELS else 0.35
    if 'LATIN' in name:
        decomposed = ud.normalize('NFD', t)
        if len(decomposed) >= 3:
            stem = decomposed[0].lower()
            if stem == 'e' and previous.lower() == 'i':
                return 6.4
            if stem == 'o' and previous.lower() in ('u', 'ư'):
                return 3.8
            return {'a': 1.2, 'e': 0.35, 'o': 0.65, 'u': 0.18}.get(stem, 0.0)
    if t in '†‡':
        fragmented = 0x80 <= raw[0] <= 0xBF
        return -2.9 if t == '‡' else (-2.5 if fragmented else -1.35)
    if t == '‰':
        return -1.8 if history.endswith('â') else -5.5
    if t == '⎯':
        return -0.6
    if t == 'ː':
        return 0.8
    if t == '～':
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history = ''
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
    else:
        _, history, decoder = carry
    raw = prefix.token_bytes[-1]
    text = decoder.decode(raw)
    value = predict(raw, text, history)
    return (doc, (history + text)[-16:], decoder), value

programs.haiku:
"""Layer 1, MLP down-projection, component 5243: a weak, sparse feature for text
fragments that are not whole characters on their own.

In plain terms, it leans positive on:
  * Thai vowel and tone marks (ิ ื ั ี่ ้ ่ ...), which attach to a preceding consonant
    and never start a word;
  * a lone small kana that writes a sound inside a word: っ ッ ｯ ゅ ャ ュ ョ ゃ ょ;
  * the replacement character U+FFFD, a lone byte of a multi-byte character, when the
    last visible text was Thai.

Everything else is predicted as 0. The sign of the activation for most other fragments
(replacement characters after Latin text, rare-token fragments) has no clean concept, so
this program explains only a few percent of the variance. The values are the rounded mean
activations of each group on training text.
"""

import unicodedata

READS = ()

SMALL_KANA = set("ッっｯゅャュョゃょ")


def is_thai_mark(ch):
    return "฀" <= ch <= "๿" and unicodedata.category(ch).startswith("M")


def is_thai_letter(ch):
    return "ก" <= ch <= "ฮ"


def step(carry, prefix, upstream):
    # carry: whether the last visible text (not a replacement character or space) was Thai.
    last_thai = carry if carry is not None else False
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        last_thai = False
    tok = prefix.token_strings[-1]
    value = 0.0
    if tok and all(is_thai_mark(c) for c in tok):
        value = 0.7
    elif len(tok) == 1 and tok in SMALL_KANA:
        value = 1.5
    elif tok == "�" and last_thai:
        value = 0.15
    if tok.strip() and tok != "�":
        last_thai = any(is_thai_letter(c) for c in tok)
    return last_thai, value

programs.sol:
"""A sparse detector of formatting boundaries and code/address landmarks.

It responds to single-token whitespace continuations, calendar-like number
endings, printing/entrypoint syntax, address beginnings, and selected quote
delimiters. Coefficients are approximate training means; other tokens get
zero. History is bounded and discarded at each document boundary.
"""
import re

READS = ()
PRINT = {'print', 'printf', 'println', 'cout', 'echo'}
ROOTS = {'workspace', 'testbed', 'usr', 'opt', 'tmp', 'root',
         'etc', 'home', 'Users', 'Volumes'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, tail = '', ''
    else:
        _, prev, tail = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    before = prev.strip()
    value = 0.0

    # Tokenization often leaves one last space after a longer indentation chunk.
    if token == ' ' and prev.isspace() and prev.endswith(' '):
        value = 1.02 if prev == ' ' else 1.33
        if len(prev) >= 16:
            value = 1.05
    elif token == '\t' and prev.isspace() and '\t' in prev:
        value = 0.65 if len(prev) == 1 else 0.8
    elif token == '\xa0' and prev.endswith('\xa0'):
        run = len(tail) - len(tail.rstrip('\xa0')) + 1
        value = 1.5 if run % 4 == 0 else (0.55 if run == 2 else 0.0)
    elif token == '``' and prev.endswith('\xa0'):
        value = 0.5

    # The fourth digit is special for dates, not for arbitrary four-digit numbers.
    elif len(token) == 1 and token in '0123456789':
        match = re.search(r'[0-9]+$', tail + token)
        number = match.group() if match else ''
        if len(number) == 4:
            year = int(number)
            if 1700 <= year < 1900:
                value = 0.22 if year < 1800 else 0.4
            elif 1900 <= year < 1930:
                value = 0.45
            elif 1930 <= year < 1970:
                value = 0.75
            elif 1970 <= year < 2030:
                value = 0.86
            elif 2030 <= year < 2100:
                value = 0.35
            start = match.start()
            if (start > 1 and tail[start - 1] == '.'
                    and tail[start - 2].isdigit()):
                value *= 0.4
        elif number in ('30', '31'):
            value = 0.45 if number == '30' else 0.24

    # Output statements are strongest at indentation or a real line break.
    elif word in PRINT:
        if word == 'cout':
            value = 1.35
        elif prev.isspace() or '\n' in prev or token.startswith('\t'):
            value = 0.8 if word == 'echo' else 1.25
        elif prev == '\\n':
            value = 0.85
        elif prev == 'n':
            value = 0.4
        elif (not token.startswith(' ') and not tail[-1:].isalnum()
              or before in ('#', ';', '{', '::')):
            value = 0.45
    elif word.lstrip('"') == 'fmt':
        value = 1.15 if '"' in token or '"' in prev else 0.75
    elif word in ('console', 'Console'):
        value = 0.65 if token[0].isspace() else 0.38
    elif word == '.log' and before == 'console':
        value = 1.3
    elif word == '.out' and before == 'System':
        value = 1.55
    elif word in ('.Println', '.Printf', '.println', '.WriteLine'):
        value = 1.1 if before in ('fmt', '.out', 'Console') else 0.5
    elif word == '.write' and before.endswith('document'):
        value = 1.1
    elif word == '.show' and before == 'plt':
        value = 0.85
    elif token == ' <<' and before == 'cout':
        value = 0.95
    elif word == 'main' and before in ('int', 'void', 'func', 'fn', 'package'):
        value = 1.4 if before in ('int', 'void') else 0.65
    elif word in ('stdio', 'iostream') and tail.endswith('<'):
        value = 1.3

    # Familiar beginnings of file paths, URLs and email domains.
    elif (word.lstrip('/') in ROOTS
          and (token.startswith('/') or tail.endswith('/'))):
        root = word.lstrip('/')
        value = 1.25
        if root in ('root', 'tmp', 'etc'):
            value = 0.95
        if token.startswith('/'):
            value = 0.55
    elif token == '/local' and tail.endswith('/usr'):
        value = 1.05
    elif word == 'www':
        value = 2.0 if tail.endswith('://') else 0.95
    elif (token.startswith('@') and not token.startswith('@@')
          and re.search(r'[A-Za-z0-9_.+%-]\Z', tail)):
        value = 1.25
    elif token in (',"', ',”', ',’') and tail and tail[-1].isalpha():
        value = 0.65
    elif token == ' "' and before == '\":':
        value = 0.35  # A JSON string value begins after the quoted key's colon.
    elif (token in (' "', " '")
          and before in ('=', '==', '=>', 'return', '<<')):
        value = 0.22

    return (doc, token, (tail + token)[-120:]), value

"""A sparse predictor for document-opening syntax and a few text formats.

Positive spikes recognize opening code declarations, triple-single-quoted
strings, title labels, Solved labels, and issue-tag prefixes. Smaller rules
cover initial greetings/function words, letters, digits (including initial
12), separators, and whitespace. Repeated middle-dot leaders are negative.

These are selected lexical/format responses, not a general model of the
component's weak background activity: unrecognized positions predict zero.
State resets at each document boundary; no future text is inspected.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, beginning, previous = 0, '', ''
    else:
        _, pos, beginning, previous = carry
    value = 0.0
    if pos == 0:
        if token == 'use':
            value = 1.64
        elif token.lower() == 'select':
            value = 1.27 if token == 'Select' else 1.90
        elif token == 'Title':
            value = 0.42
        elif token == '+\\':
            value = 1.63
        elif token == 'class':
            value = 1.10
        elif token == 'def':
            value = 0.89
        elif token == 'package':
            value = -0.50
        elif token.startswith("'''"):
            value = 1.38 if '\n' in token else 1.71
        elif token == '<!':
            value = -2.53
        elif token == ' .':
            value = -1.75
        elif token == '<|im_start|>':
            value = -0.26
        elif token == '<|endoftext|>':
            value = 1.55
        elif token == '\r':
            value = -2.05
        elif token == '\r\n':
            value = 1.27
        elif token in ('Welcome', 'Hello', 'Hi', 'hey'):
            value = -0.95
        elif token in ('When', 'We', 'You', 'An'):
            value = -0.95
        elif token in ('The', ' the'):
            value = -0.15
        elif token in ('And', ' And', 'That'):
            value = 0.88
        elif token.isspace():
            value = 0.30 if '\n' in token else 0.12
        elif token == 'I':
            value = -0.25
        elif len(token) == 1 and token.isascii() and token.isalpha():
            value = 0.36
        elif token.isascii() and token.isdigit():
            value = -0.25
    elif pos == 1 and previous == 'Title' and token == ':':
        value = 4.33
    elif pos == 1 and previous == '1' and token == '2':
        value = -1.79
    elif pos == 1 and previous == 'S' and token == 'olved':
        value = 1.27
    elif beginning == '<issue_start><' and token == 'issue':
        value = 1.45
    if token == '\r' and not beginning.strip('\r'):
        value = -2.05
    if token and set(token) == {'·'} and len(token) > 1:
        value = -0.545
    if len(beginning) < 64:
        beginning += token
    return (doc, pos + 1, beginning, token), value

"""Approximate the component's document-opening transient.

Some source-file openers have large negative values; ordinary initial words have
smaller positive values. An unchanged run of the opening token preserves
that response (notably carriage returns and decorative separators).
After the opening run, predict almost zero, except for a package-name
prefix and a small average response to incomplete UTF-8 tokens.
This omits most of the component's weaker, word-specific variation.
"""
import regex
import unicodedata

READS = ()

# Bare source-language declarations, not keywords preceded by whitespace.
DECLARATIONS = {
    'class': -2.26,
    'function': -1.28,
    'def': -0.55,
    'void': -1.73,
    'const': -0.88,
    'let': -1.02,
    'var': -0.48,
    'module': -0.96,
    'package': -0.57,
    'import': 0.45,
    'from': -0.52,
    'using': 0.78,
    'namespace': 0.70,
}


def opening_value(text):
    if text in DECLARATIONS:
        return DECLARATIONS[text]
    if text == '//\n':
        return -8.28
    if text == '<!':
        return -4.76
    if text == '\r':
        return -5.48
    if text == '^^^^':
        return 3.03
    if text == '··':
        return 2.59
    if text.startswith('#') and text[1:] in {'include', 'pragma'}:
        return 1.08
    if text.startswith('<|'):
        return -0.105
    if not text.strip():
        if '\t' in text:
            return 0.57
        if '\n' in text:
            return 0.39
        return -0.06
    word = text.strip()
    if word.isdigit():
        return 0.0
    if all(unicodedata.category(c).startswith('P') for c in word):
        return 0.0
    if regex.search(r'\p{Script=Cyrillic}', word):
        return 0.11
    if word.isascii() and word.isupper():
        return 0.12
    if word.isascii() and word.istitle():
        return 0.48
    return 0.39


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    previous = None
    if carry is None or carry[0] != doc:
        opening_run = True
    else:
        previous = carry[1]
        opening_run = carry[2] and raw == previous
    value = opening_value(token) if opening_run else 0.0
    if not opening_run and '\ufffd' in token:
        value = 0.02
    # The conventional reversed-domain start of a Java package name.
    if carry is not None and carry[0] == doc and carry[2]:
        if previous == b'package' and token == ' com':
            value = 1.11
    return (doc, raw, opening_run), value

programs.haiku:
"""layers.1.mlp.down_proj:5246: a document-start detector.

The component is almost silent inside a document. Its activity sits on the first
token of each document (the token right after a document break, or the first token
of a row), where it takes a value set by what that token is:

- a bare comment opener ("//" + newline) or "<!" (as in "<!DOCTYPE"): strongly negative;
- a code declaration or file opener (class, function, const, module, def, var,
  package, from, "#!/", "["): moderately negative;
- an ordinary word (letters, with or without a leading space): moderately positive;
- anything else (punctuation, digits, whitespace): slightly positive.

Every other position predicts 0. Within a document the activation is small, diffuse
and depends on the particular token rather than on any simple class, so 0 is the
best readable guess there.

The values are rounded means from training text; the word/other split is the bulk
of what this program captures.
"""

READS = ()

# First tokens that open a file or block of code, with their typical sign.
COMMENT_OPENERS = {"//\n", "<!"}
CODE_OPENERS = {"class", "function", "const", "module", "def", "var", "package", "from", "#!/", "["}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    body = token.lstrip(" ")
    # Document start: the first token of the row, or the first token after a document change.
    starts_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document or not body:
        return None, 0.0
    if token in COMMENT_OPENERS:
        return None, -6.0
    if body in CODE_OPENERS:
        return None, -1.0
    if body[0].isalpha():
        return None, 0.37
    return None, 0.1
